--
-- Name: ap_backfill_supplier_payment_documents(uuid, uuid); Type: FUNCTION; Schema: public; Owner: migration_admin
--

CREATE FUNCTION public.ap_backfill_supplier_payment_documents(p_company_id uuid DEFAULT NULL::uuid, p_batch_id uuid DEFAULT gen_random_uuid()) RETURNS TABLE(result_batch_id uuid, result_outcome text, result_reason text, line_count bigint, line_amount numeric)
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- ONE snapshot, and all four statements below read it. See 682: the payment
  -- arm's own mints raise a supplier's credit, so a refund arm re-evaluating
  -- the view between writes could mint a line the same batch had already logged
  -- over-ceiling.
  --
  -- DROP first: two calls in one transaction — which the integration suite
  -- makes, and an operator running two tenants back to back would — otherwise
  -- die on "relation already exists" before either has written anything.
  -- `pg_temp.` is spelled out because pg_temp is searched FIRST, and a function
  -- that writes financial documents must not take its input from a relation a
  -- caller can substitute.
  DROP TABLE IF EXISTS pg_temp.ap_pdb_run;
  CREATE TEMP TABLE ap_pdb_run ON COMMIT DROP AS
    SELECT * FROM ap_payment_document_backfill_candidates c
     WHERE p_company_id IS NULL OR c.company_id = p_company_id;

  -- ── 683: the cumulative ceiling ──────────────────────────────────────────
  --
  -- BEFORE the skip log, so a line demoted here is logged once, under the
  -- outcome it ends on. Walking each supplier's refunds in order and carrying
  -- only what was ACCEPTED — see the header for why the obvious window
  -- function is wrong.
  WITH RECURSIVE seq AS (
    SELECT r.bank_transaction_id, r.company_id, r.supplier_id, r.amount,
           r.on_account_credit,
           ROW_NUMBER() OVER (PARTITION BY r.company_id, r.supplier_id
                              ORDER BY r.transaction_date, r.bank_transaction_id) AS n
      FROM ap_pdb_run r
     WHERE r.outcome = 'create_refund'
  ),
  walk AS (
    SELECT s.bank_transaction_id, s.company_id, s.supplier_id, s.n,
           (s.amount <= s.on_account_credit) AS accepted,
           CASE WHEN s.amount <= s.on_account_credit THEN s.amount ELSE 0 END AS consumed
      FROM seq s
     WHERE s.n = 1
    UNION ALL
    SELECT s.bank_transaction_id, s.company_id, s.supplier_id, s.n,
           (s.amount <= s.on_account_credit - w.consumed) AS accepted,
           w.consumed
             + CASE WHEN s.amount <= s.on_account_credit - w.consumed THEN s.amount ELSE 0 END
      FROM walk w
      JOIN seq s
        ON s.company_id = w.company_id
       AND s.supplier_id = w.supplier_id
       AND s.n = w.n + 1
  )
  UPDATE ap_pdb_run r
     SET outcome = 'refund_exceeds_credit'
    FROM walk w
   WHERE r.bank_transaction_id = w.bank_transaction_id
     AND NOT w.accepted;

  INSERT INTO ap_payment_document_backfill (
    batch_id, company_id, bank_transaction_id, journal_entry_id,
    supplier_id, supplier_payment_id, amount, outcome, reason
  )
  SELECT p_batch_id, c.company_id, c.bank_transaction_id, c.journal_entry_id,
         c.supplier_id, NULL, c.amount, 'skipped', c.outcome
  FROM ap_pdb_run c
  WHERE c.outcome NOT IN ('create', 'create_refund');

  -- The document, and only the document. No journal, no allocation, no
  -- `amount_paid`. See 615 for why `created_by` is the journal's author and why
  -- `payment_number` is left to trg_sp_payment_number.
  WITH cand AS (
    SELECT * FROM ap_pdb_run c WHERE c.outcome = 'create'
  ),
  ins AS (
    INSERT INTO supplier_payments (
      company_id, supplier_id, payment_date, total_amount, payment_method,
      bank_account_id, reference, description, status, gl_journal_entry_id,
      created_by, approved_by, approved_at, processed_at
    )
    SELECT cand.company_id, cand.supplier_id, cand.transaction_date, cand.amount, 'eft',
           cand.bank_account_id, cand.bank_transaction_id::TEXT, cand.description,
           'processed', cand.journal_entry_id,
           cand.journal_created_by, cand.journal_created_by, NOW(), NOW()
    FROM cand
    RETURNING id, company_id, supplier_id, reference, gl_journal_entry_id, total_amount
  )
  INSERT INTO ap_payment_document_backfill (
    batch_id, company_id, bank_transaction_id, journal_entry_id,
    supplier_id, supplier_payment_id, amount, outcome, reason
  )
  SELECT p_batch_id, ins.company_id, ins.reference::UUID, ins.gl_journal_entry_id,
         ins.supplier_id, ins.id, ins.total_amount, 'created', 'backfilled'
  FROM ins;

  -- The refund arm. `-cand.amount` and `'refund'` are the whole difference.
  --
  -- The LOG row carries the GROSS line value, not the signed total: it sits
  -- beside skipped rows carrying the same gross, and a batch summary whose
  -- amounts change sign by outcome cannot be read down a column.
  WITH cand AS (
    SELECT * FROM ap_pdb_run c WHERE c.outcome = 'create_refund'
  ),
  ins AS (
    INSERT INTO supplier_payments (
      company_id, supplier_id, payment_date, total_amount, payment_method,
      bank_account_id, reference, description, status, gl_journal_entry_id,
      created_by, approved_by, approved_at, processed_at
    )
    SELECT cand.company_id, cand.supplier_id, cand.transaction_date, -cand.amount, 'refund',
           cand.bank_account_id, cand.bank_transaction_id::TEXT, cand.description,
           'processed', cand.journal_entry_id,
           cand.journal_created_by, cand.journal_created_by, NOW(), NOW()
    FROM cand
    RETURNING id, company_id, supplier_id, reference, gl_journal_entry_id, total_amount
  )
  INSERT INTO ap_payment_document_backfill (
    batch_id, company_id, bank_transaction_id, journal_entry_id,
    supplier_id, supplier_payment_id, amount, outcome, reason
  )
  SELECT p_batch_id, ins.company_id, ins.reference::UUID, ins.gl_journal_entry_id,
         ins.supplier_id, ins.id, ABS(ins.total_amount), 'created', 'backfilled_refund'
  FROM ins;

  RETURN QUERY
  SELECT p_batch_id, l.outcome, l.reason, COUNT(*)::BIGINT, COALESCE(SUM(l.amount), 0)
  FROM ap_payment_document_backfill l
  WHERE l.batch_id = p_batch_id
  GROUP BY l.outcome, l.reason
  ORDER BY l.outcome, l.reason;
END;
$$;


ALTER FUNCTION public.ap_backfill_supplier_payment_documents(p_company_id uuid, p_batch_id uuid) OWNER TO migration_admin;

--
-- Name: ap_journal_entry_is_reversed(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ap_journal_entry_is_reversed(p_company_id uuid, p_journal_entry_id uuid) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
  SELECT EXISTS (
    SELECT 1
      FROM gl_journal_entries d
     WHERE d.id = p_journal_entry_id
       AND d.company_id = p_company_id
       AND (d.reversed_at IS NOT NULL
            OR d.status = 'reversed'
            OR EXISTS (SELECT 1
                         FROM gl_journal_entries r
                        WHERE r.company_id = p_company_id
                          AND r.reversal_of_id = d.id
                          AND r.status = 'posted'))
  );
$$;


ALTER FUNCTION public.ap_journal_entry_is_reversed(p_company_id uuid, p_journal_entry_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION ap_journal_entry_is_reversed(p_company_id uuid, p_journal_entry_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.ap_journal_entry_is_reversed(p_company_id uuid, p_journal_entry_id uuid) IS 'TRUE when a journal entry has been reversed, by any of the three ways this ledger records one: reversed_at, status, or a POSTED entry naming it in reversal_of_id. The single definition the AP backfill classifier reads.';


--
-- Name: ap_rollback_supplier_payment_document_backfill(uuid); Type: FUNCTION; Schema: public; Owner: migration_admin
--

CREATE FUNCTION public.ap_rollback_supplier_payment_document_backfill(p_batch_id uuid) RETURNS TABLE(deleted_count bigint, deleted_amount numeric)
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_blocked TEXT;
BEGIN
  SELECT STRING_AGG(sp.id::TEXT, ', ')
    INTO v_blocked
  FROM ap_payment_document_backfill l
  JOIN supplier_payments sp ON sp.id = l.supplier_payment_id
  WHERE l.batch_id = p_batch_id
    AND l.outcome = 'created'
    AND l.rolled_back_at IS NULL
    AND (sp.status <> 'processed'
         OR EXISTS (SELECT 1 FROM payment_allocations pa WHERE pa.payment_id = sp.id)
         -- The legacy twin. Zero rows and no writer today (see the note in
         -- ap/unappliedPaymentService.ts), and it cascades on delete exactly
         -- like the live one — so a rollback that ignores it destroys those
         -- rows in silence the day anything starts writing them.
         OR EXISTS (SELECT 1 FROM supplier_payment_allocations spa WHERE spa.payment_id = sp.id));

  IF v_blocked IS NOT NULL THEN
    RAISE EXCEPTION
      'Rollback refused: payment(s) % have been applied or their status changed since the backfill. '
      'Reverse those applications first, or roll back the rest by hand.', v_blocked;
  END IF;

  -- Marked BEFORE the delete, in its own statement. Doing both in one
  -- data-modifying CTE has the FK's ON DELETE SET NULL trigger updating log
  -- rows the same command has already updated.
  UPDATE ap_payment_document_backfill l
     SET rolled_back_at = NOW()
   WHERE l.batch_id = p_batch_id
     AND l.outcome = 'created'
     AND l.rolled_back_at IS NULL
     AND l.supplier_payment_id IS NOT NULL;

  WITH gone AS (
    DELETE FROM supplier_payments sp
     USING ap_payment_document_backfill l
     WHERE l.batch_id = p_batch_id
       AND l.outcome = 'created'
       AND l.rolled_back_at IS NOT NULL
       AND sp.id = l.supplier_payment_id
    RETURNING sp.total_amount
  )
  SELECT COUNT(*)::BIGINT, COALESCE(SUM(gone.total_amount), 0)
    INTO deleted_count, deleted_amount
  FROM gone;

  RETURN NEXT;
END;
$$;


ALTER FUNCTION public.ap_rollback_supplier_payment_document_backfill(p_batch_id uuid) OWNER TO migration_admin;

--
-- Name: ap_supplier_on_account_credit(uuid, uuid, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ap_supplier_on_account_credit(p_company_id uuid, p_supplier_id uuid, p_as_at date) RETURNS numeric
    LANGUAGE sql STABLE
    AS $$
  SELECT COALESCE(SUM(
           sp.total_amount
           - LEAST(COALESCE(alloc.allocated, 0), GREATEST(sp.total_amount, 0))
         ), 0)
    FROM supplier_payments sp
    LEFT JOIN LATERAL (
      SELECT SUM(pa.amount_allocated) AS allocated
        FROM payment_allocations pa
       WHERE pa.payment_id = sp.id
    ) alloc ON TRUE
   WHERE sp.company_id = p_company_id
     AND sp.supplier_id = p_supplier_id
     AND sp.status IN ('processed', 'reconciled')
     AND sp.payment_date <= p_as_at;
$$;


ALTER FUNCTION public.ap_supplier_on_account_credit(p_company_id uuid, p_supplier_id uuid, p_as_at date) OWNER TO postgres;

--
-- Name: FUNCTION ap_supplier_on_account_credit(p_company_id uuid, p_supplier_id uuid, p_as_at date); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.ap_supplier_on_account_credit(p_company_id uuid, p_supplier_id uuid, p_as_at date) IS 'What a supplier has sitting on account as at a date: the sum of its processed and reconciled payments'' unapplied remainders, with earlier refunds netted off because a refund is a remainder of the other sign. The single definition the refund ceiling reads, on the live path and in the back-fill classification alike.';


--
-- Name: approval_actor_rank(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.approval_actor_rank(p_role text) RETURNS integer
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
  SELECT CASE p_role
    WHEN 'super_admin' THEN 8 WHEN 'owner' THEN 7 WHEN 'system' THEN 6 WHEN 'admin' THEN 5
    WHEN 'manager' THEN 4 WHEN 'accountant' THEN 3 WHEN 'bookkeeper' THEN 2
    WHEN 'storeman' THEN 1 WHEN 'technician' THEN 1 WHEN 'user' THEN 1 WHEN 'viewer' THEN 0
    ELSE 0
  END
$$;


ALTER FUNCTION public.approval_actor_rank(p_role text) OWNER TO postgres;

