--
-- Name: approval_company_member_name(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.approval_company_member_name(p_company_id uuid, p_user_id text) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
DECLARE
  v_name pg_catalog.text;
BEGIN
  IF auth.uid() IS NULL THEN
    RETURN NULL;
  END IF;
  IF app.current_company_id() IS NULL OR app.current_company_id() IS DISTINCT FROM p_company_id THEN
    RAISE EXCEPTION 'approval_company_member_name: answers only for the caller''s own company'
      USING ERRCODE = '42501';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.company_users cu WHERE cu.company_id = p_company_id AND cu.user_id = auth.uid()
  ) THEN
    RAISE EXCEPTION 'approval_company_member_name: caller is not a member of this company'
      USING ERRCODE = '42501';
  END IF;
  IF p_user_id IS NULL THEN
    RETURN NULL;
  END IF;

  -- The target must ALSO be a member of p_company_id: bounds the lookup to
  -- exactly what an approval_requests row already implies (requested_by and
  -- decided_by are always this company's members), not an arbitrary id.
  SELECT NULLIF(TRIM(BOTH ' ' FROM COALESCE(u.first_name, '') || ' ' || COALESCE(u.last_name, '')), '')
    INTO v_name
  FROM public.users u
  JOIN public.company_users cu ON cu.user_id = u.id AND cu.company_id = p_company_id
  WHERE u.id = p_user_id;

  IF v_name IS NOT NULL THEN
    RETURN v_name;
  END IF;

  -- No name on file (GoTrue user with an email but no profile name yet): the
  -- email is still an honest, resolvable identifier — closer to the truth
  -- than "Unknown", which reads as "nobody knows who raised this".
  RETURN (
    SELECT u.email FROM public.users u
    JOIN public.company_users cu ON cu.user_id = u.id AND cu.company_id = p_company_id
    WHERE u.id = p_user_id
  );
END
$$;


ALTER FUNCTION public.approval_company_member_name(p_company_id uuid, p_user_id text) OWNER TO postgres;

--
-- Name: approval_company_member_profile(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.approval_company_member_profile(p_company_id uuid, p_user_id text) RETURNS TABLE(email text, first_name text, last_name text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
BEGIN
  IF auth.uid() IS NULL THEN
    RETURN;
  END IF;
  IF app.current_company_id() IS NULL OR app.current_company_id() IS DISTINCT FROM p_company_id THEN
    RAISE EXCEPTION 'approval_company_member_profile: answers only for the caller''s own company'
      USING ERRCODE = '42501';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.company_users cu WHERE cu.company_id = p_company_id AND cu.user_id = auth.uid()
  ) THEN
    RAISE EXCEPTION 'approval_company_member_profile: caller is not a member of this company'
      USING ERRCODE = '42501';
  END IF;
  IF p_user_id IS NULL THEN
    RETURN;
  END IF;

  RETURN QUERY
  SELECT u.email::pg_catalog.text, u.first_name::pg_catalog.text, u.last_name::pg_catalog.text
  FROM public.users u
  JOIN public.company_users cu ON cu.user_id = u.id AND cu.company_id = p_company_id
  WHERE u.id = p_user_id;
END
$$;


ALTER FUNCTION public.approval_company_member_profile(p_company_id uuid, p_user_id text) OWNER TO postgres;

--
-- Name: approval_company_other_members(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.approval_company_other_members(p_company_id uuid, p_user_id text) RETURNS TABLE(user_id text, role text, is_active boolean, status text, suspended_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
BEGIN
  IF auth.uid() IS NULL OR auth.uid() IS DISTINCT FROM p_user_id THEN
    RAISE EXCEPTION 'approval_company_other_members: may only be asked on behalf of the caller'
      USING ERRCODE = '42501';
  END IF;
  IF app.current_company_id() IS NULL OR app.current_company_id() IS DISTINCT FROM p_company_id THEN
    RAISE EXCEPTION 'approval_company_other_members: answers only for the request''s own company'
      USING ERRCODE = '42501';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.company_users cu JOIN public.users u ON u.id = cu.user_id
    WHERE cu.company_id = p_company_id AND cu.user_id = p_user_id
  ) THEN
    RAISE EXCEPTION 'approval_company_other_members: cannot see the caller''s own membership in this company'
      USING ERRCODE = '42501';
  END IF;
  RETURN QUERY
    SELECT cu.user_id::pg_catalog.text, cu.role::pg_catalog.text, u.is_active, u.status::pg_catalog.text, u.suspended_at
    FROM public.company_users cu
    LEFT JOIN public.users u ON u.id = cu.user_id
    WHERE cu.company_id = p_company_id AND cu.user_id <> p_user_id;
END
$$;


ALTER FUNCTION public.approval_company_other_members(p_company_id uuid, p_user_id text) OWNER TO postgres;

--
-- Name: approval_credit_note_gate_amount(numeric, numeric, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.approval_credit_note_gate_amount(p_total numeric, p_subtotal numeric, p_tax numeric) RETURNS numeric
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
  SELECT GREATEST(ABS(COALESCE(p_total, 0)), ABS(COALESCE(p_subtotal, 0) + COALESCE(p_tax, 0)))
$$;


