--
-- Name: approval_document_authors(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.approval_document_authors(p_company_id uuid, p_document_type text, p_document_id uuid) RETURNS uuid[]
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
  SELECT CASE p_document_type
    WHEN 'supplier_invoice' THEN (
      SELECT public.approval_add_author(si.content_authors, si.created_by)
      FROM public.supplier_invoices si
      WHERE si.id = p_document_id AND si.company_id = p_company_id AND si.deleted_at IS NULL
    )
    WHEN 'customer_credit_note' THEN (
      SELECT public.approval_add_author(cn.content_authors, cn.created_by)
      FROM public.credit_notes cn
      WHERE cn.id = p_document_id AND cn.company_id = p_company_id AND cn.type = 'customer'
    )
    WHEN 'supplier_credit_note' THEN (
      SELECT public.approval_add_author(cn.content_authors, cn.created_by)
      FROM public.credit_notes cn
      WHERE cn.id = p_document_id AND cn.company_id = p_company_id AND cn.type = 'supplier'
    )
    WHEN 'customer_invoice' THEN (
      SELECT b.base || ARRAY(
        SELECT d.author FROM (
          SELECT qa.author FROM public.customer_quotes q
          CROSS JOIN LATERAL unnest(q.content_authors || ARRAY[q.created_by]) qa(author)
          WHERE q.converted_invoice_id = ci.id AND q.company_id = ci.company_id
          UNION
          SELECT sa.author FROM public.customer_sales_orders so
          CROSS JOIN LATERAL unnest(so.content_authors || ARRAY[so.created_by]) sa(author)
          WHERE so.invoice_id = ci.id AND so.company_id = ci.company_id
          UNION
          SELECT qa.author FROM public.customer_sales_orders so
          JOIN public.customer_quotes q ON (q.id = so.quote_id OR q.converted_order_id = so.id)
            AND q.company_id = ci.company_id
          CROSS JOIN LATERAL unnest(q.content_authors || ARRAY[q.created_by]) qa(author)
          WHERE so.invoice_id = ci.id AND so.company_id = ci.company_id
          UNION
          SELECT ta.author FROM public.time_entries te
          CROSS JOIN LATERAL unnest(te.content_authors) ta(author)
          WHERE te.invoice_id = ci.id AND te.company_id = ci.company_id
        ) d(author)
        WHERE d.author IS NOT NULL AND d.author <> ALL (b.base)
        ORDER BY d.author)
      FROM public.customer_invoices ci
      CROSS JOIN LATERAL (
        SELECT public.approval_add_author(ci.content_authors,
          CASE WHEN ci.created_by ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
               THEN ci.created_by::pg_catalog.uuid END) AS base
      ) b
      WHERE ci.id = p_document_id AND ci.company_id = p_company_id AND ci.deleted_at IS NULL
    )
    WHEN 'supplier_payment' THEN (
      SELECT public.approval_supplier_payment_authors(sp.company_id, sp.id)
      FROM public.supplier_payments sp
      WHERE sp.id = p_document_id AND sp.company_id = p_company_id AND sp.batch_id IS NULL
    )
    WHEN 'payment_batch' THEN (
      SELECT b2.base || ARRAY(
        SELECT DISTINCT m.author FROM public.supplier_payments sp
        CROSS JOIN LATERAL unnest(public.approval_supplier_payment_authors(sp.company_id, sp.id)) m(author)
        WHERE sp.batch_id = b.id AND sp.company_id = b.company_id
          AND m.author IS NOT NULL AND m.author <> ALL (b2.base)
        ORDER BY m.author)
      FROM public.supplier_payment_batches b
      CROSS JOIN LATERAL (SELECT public.approval_add_author(b.content_authors, b.created_by) AS base) b2
      WHERE b.id = p_document_id AND b.company_id = p_company_id
    )
    WHEN 'manual_journal' THEN (
      SELECT public.approval_add_author(je.content_authors, je.created_by)
      FROM public.gl_journal_entries je
      WHERE je.id = p_document_id AND je.company_id = p_company_id
    )
  END
$_$;


ALTER FUNCTION public.approval_document_authors(p_company_id uuid, p_document_type text, p_document_id uuid) OWNER TO postgres;

--
-- Name: approval_document_digest(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.approval_document_digest(p_company_id uuid, p_document_type text, p_document_id uuid) RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
  SELECT CASE p_document_type
    WHEN 'supplier_invoice' THEN (
      SELECT encode(sha256(convert_to(jsonb_build_array(
        si.supplier_id, si.invoice_number, si.invoice_date,
        si.currency, si.currency_code, trim_scale(si.exchange_rate),
        trim_scale(si.subtotal), trim_scale(si.tax_rate), trim_scale(si.tax_amount),
        trim_scale(si.total_amount), trim_scale(si.functional_total),
        si.project_id, si.cost_center_id, si.is_drc,
        COALESCE((
          SELECT jsonb_agg(jsonb_build_array(
                   sii.gl_account_id, sii.description, trim_scale(sii.quantity),
                   trim_scale(sii.unit_price), trim_scale(sii.tax_rate), trim_scale(sii.tax_amount),
                   trim_scale(sii.line_total), sii.project_id, sii.cost_center_id,
                   sii.vat_classification, sii.cc1_id, sii.cc2_id, sii.bu_id)
                 ORDER BY sii.created_at, sii.description, sii.gl_account_id, sii.quantity,
                          sii.unit_price, sii.tax_rate, sii.tax_amount, sii.line_total,
                          sii.project_id, sii.cost_center_id, sii.vat_classification,
                          sii.cc1_id, sii.cc2_id, sii.bu_id, sii.id)
          FROM public.supplier_invoice_items sii
          WHERE sii.supplier_invoice_id = si.id
        ), '[]'::jsonb)
      )::TEXT, 'UTF8')), 'hex')
      FROM public.supplier_invoices si
      WHERE si.id = p_document_id AND si.company_id = p_company_id AND si.deleted_at IS NULL
    )
    WHEN 'customer_credit_note' THEN (
      SELECT encode(sha256(convert_to(jsonb_build_array(
        cn.type, cn.credit_note_number, cn.client_id, cn.customer_invoice_id,
        cn.supplier_id, cn.supplier_invoice_id, cn.credit_date, cn.currency,
        trim_scale(cn.subtotal), trim_scale(cn.tax_rate), trim_scale(cn.tax_amount),
        trim_scale(cn.total_amount), cn.project_id, cn.cost_center_id,
        cn.cc1_id, cn.cc2_id, cn.bu_id
      )::TEXT, 'UTF8')), 'hex')
      FROM public.credit_notes cn
      WHERE cn.id = p_document_id AND cn.company_id = p_company_id AND cn.type = 'customer'
    )
    WHEN 'supplier_credit_note' THEN (
      SELECT encode(sha256(convert_to(jsonb_build_array(
        cn.type, cn.credit_note_number, cn.client_id, cn.customer_invoice_id,
        cn.supplier_id, cn.supplier_invoice_id, cn.credit_date, cn.currency,
        trim_scale(cn.subtotal), trim_scale(cn.tax_rate), trim_scale(cn.tax_amount),
        trim_scale(cn.total_amount), cn.project_id, cn.cost_center_id,
        cn.cc1_id, cn.cc2_id, cn.bu_id
      )::TEXT, 'UTF8')), 'hex')
      FROM public.credit_notes cn
      WHERE cn.id = p_document_id AND cn.company_id = p_company_id AND cn.type = 'supplier'
    )
    WHEN 'customer_invoice' THEN (
      SELECT encode(sha256(convert_to(jsonb_build_array(
        ci.customer_id, ci.client_id, ci.invoice_number, ci.invoice_date,
        ci.currency_code, trim_scale(ci.exchange_rate),
        trim_scale(ci.subtotal), trim_scale(ci.tax_rate), trim_scale(ci.tax_amount),
        trim_scale(ci.total_amount), trim_scale(ci.functional_total), ci.project_id,
        COALESCE((
          SELECT jsonb_agg(jsonb_build_array(
                   cii.description, trim_scale(cii.quantity), trim_scale(cii.unit_price),
                   trim_scale(cii.amount), trim_scale(cii.tax_rate), cii.gl_account_id,
                   cii.project_id, cii.currency_code, cii.cc1_id, cii.cc2_id, cii.bu_id)
                 ORDER BY cii.created_at, cii.description, cii.quantity, cii.unit_price,
                          cii.amount, cii.tax_rate, cii.gl_account_id, cii.project_id, cii.currency_code,
                          cii.cc1_id, cii.cc2_id, cii.bu_id, cii.id)
          FROM public.customer_invoice_items cii
          WHERE cii.invoice_id = ci.id
        ), '[]'::jsonb)
      )::TEXT, 'UTF8')), 'hex')
      FROM public.customer_invoices ci
      WHERE ci.id = p_document_id AND ci.company_id = p_company_id AND ci.deleted_at IS NULL
    )
    WHEN 'supplier_payment' THEN (
      SELECT encode(sha256(convert_to(
        public.approval_supplier_payment_content(sp.company_id, sp.id)::TEXT, 'UTF8')), 'hex')
      FROM public.supplier_payments sp
      WHERE sp.id = p_document_id AND sp.company_id = p_company_id AND sp.batch_id IS NULL
    )
    WHEN 'payment_batch' THEN (
      SELECT encode(sha256(convert_to(jsonb_build_array(
        b.batch_date, b.payment_method, b.bank_account_id, trim_scale(b.total_amount),
        COALESCE((
          SELECT jsonb_agg(m.content ORDER BY m.content::TEXT)
          FROM (SELECT public.approval_supplier_payment_content(sp.company_id, sp.id) AS content
                FROM public.supplier_payments sp
                WHERE sp.batch_id = b.id AND sp.company_id = b.company_id) m
        ), '[]'::jsonb)
      )::TEXT, 'UTF8')), 'hex')
      FROM public.supplier_payment_batches b
      WHERE b.id = p_document_id AND b.company_id = p_company_id
    )
    WHEN 'manual_journal' THEN (
      SELECT encode(sha256(convert_to(jsonb_build_array(
        je.entry_date, je.description, je.reference, je.project_id, je.cost_center_id,
        je.is_intercompany, je.intercompany_company_id,
        COALESCE((
          SELECT jsonb_agg(jsonb_build_array(
                   jl.gl_account_id, trim_scale(jl.debit), trim_scale(jl.credit), jl.description, jl.vat_type,
                   jl.cc1_id, jl.cc2_id, jl.bu_id, jl.project_id, jl.cost_center_id)
                 ORDER BY jl.created_at, jl.gl_account_id, jl.debit, jl.credit, jl.description, jl.vat_type,
                          jl.cc1_id, jl.cc2_id, jl.bu_id, jl.project_id, jl.cost_center_id, jl.id)
          FROM public.gl_journal_lines jl
          WHERE jl.journal_entry_id = je.id
        ), '[]'::jsonb)
      )::TEXT, 'UTF8')), 'hex')
      FROM public.gl_journal_entries je
      WHERE je.id = p_document_id AND je.company_id = p_company_id
    )
  END
$$;


ALTER FUNCTION public.approval_document_digest(p_company_id uuid, p_document_type text, p_document_id uuid) OWNER TO postgres;

--
-- Name: approval_enforcement_bank_baseline(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.approval_enforcement_bank_baseline(p_company_id uuid, p_actor text) RETURNS integer
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
DECLARE
  v_count pg_catalog.int4;
BEGIN
  IF EXISTS (SELECT 1 FROM public.supplier_bank_verifications v WHERE v.company_id = p_company_id)
     OR EXISTS (SELECT 1 FROM public.audit_log a WHERE a.company_id = p_company_id AND a.entity_type = 'approval_enforcement'
                  AND a.entity_ref = 'supplier_bank_details' AND a.action = 'create') THEN
    RETURN 0;
  END IF;
  PERFORM 1 FROM public.suppliers s WHERE s.company_id = p_company_id ORDER BY s.id FOR SHARE;
  WITH inserted AS (
    INSERT INTO public.supplier_bank_verifications (company_id, supplier_id, fingerprint, kind, verified_by)
    SELECT s.company_id, s.id,
           public.supplier_bank_fingerprint(s.bank_name, s.bank_account_number, s.bank_branch_code, s.bank_account_type, s.bank_account_holder),
           'baseline', p_actor
    FROM public.suppliers s
    WHERE s.company_id = p_company_id AND s.deleted_at IS NULL
      AND NOT (p_actor = ANY (COALESCE(s.bank_details_setters::pg_catalog.text[], '{}')))
      AND public.supplier_bank_details_present(s.bank_name, s.bank_account_number, s.bank_branch_code, s.bank_account_type, s.bank_account_holder)
      AND NOT EXISTS (SELECT 1 FROM public.supplier_bank_verifications v WHERE v.company_id = s.company_id AND v.supplier_id = s.id)
    RETURNING 1)
  SELECT pg_catalog.count(*)::pg_catalog.int4 INTO v_count FROM inserted;
  RETURN v_count;
END
$$;


ALTER FUNCTION public.approval_enforcement_bank_baseline(p_company_id uuid, p_actor text) OWNER TO postgres;

--
-- Name: approval_enforcement_bank_verifier_role(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.approval_enforcement_bank_verifier_role(p_company_id uuid) RETURNS text
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
DECLARE
  v_strictest pg_catalog.text := 'admin';
  v_type pg_catalog.text;
  v_role pg_catalog.text;
BEGIN
  FOREACH v_type IN ARRAY ARRAY['supplier_payment', 'payment_batch'] LOOP
    v_role := public.approval_enforcement_strictest_role(p_company_id, v_type);
    IF v_role IS NOT NULL AND public.approval_required_rank(v_role) > public.approval_required_rank(v_strictest) THEN
      v_strictest := v_role;
    END IF;
  END LOOP;
  RETURN v_strictest;
END
$$;


ALTER FUNCTION public.approval_enforcement_bank_verifier_role(p_company_id uuid) OWNER TO postgres;

--
-- Name: approval_enforcement_set(uuid, text, boolean, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.approval_enforcement_set(p_company_id uuid, p_document_type text, p_enabled boolean, p_actor text) RETURNS TABLE(id uuid, document_type text, enabled_at timestamp with time zone, enabled_by text, baseline_suppliers integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
#variable_conflict use_column
DECLARE
  v_role pg_catalog.text;
  v_bank pg_catalog.bool := p_document_type = 'supplier_bank_details';
  v_bank_rule pg_catalog.bool := p_document_type = 'bank_rule';
  v_types pg_catalog.text[] := CASE WHEN p_document_type IN ('supplier_payment', 'payment_batch')
                                    THEN ARRAY['supplier_payment', 'payment_batch'] ELSE ARRAY[p_document_type] END;
  v_type pg_catalog.text;
  v_session pg_catalog.text;
  v_verifier pg_catalog.text;
  v_approver pg_catalog.text;
  v_own pg_catalog.text;
  v_strictest pg_catalog.text;
  v_rule_role pg_catalog.text;
  v_row public.approval_enforcement;
  v_baseline pg_catalog.int4;
  v_extra pg_catalog.jsonb;
BEGIN
  PERFORM public.approval_rule_assert_caller(p_company_id, p_actor);
  IF p_enabled IS NULL THEN
    RAISE EXCEPTION 'enabled must be true or false' USING ERRCODE = 'RB020';
  END IF;
  v_role := public.approval_rule_actor_role(p_company_id, p_actor);
  IF p_enabled AND (p_document_type IS NULL OR p_document_type <> ALL (ARRAY['supplier_invoice', 'customer_credit_note',
       'supplier_credit_note', 'customer_invoice', 'supplier_payment', 'payment_batch', 'manual_journal',
       'supplier_bank_details', 'bank_rule']::pg_catalog.text[])) THEN
    RAISE EXCEPTION 'Approval enforcement is not available for % yet', p_document_type
      USING ERRCODE = 'RB010', DETAIL = COALESCE(p_document_type, '');
  END IF;
  IF v_bank THEN
    -- A person in their own session, enabling and disabling alike (assertVerifyingSession).
    v_session := public.approval_request_session_actor();
    IF v_session <> 'self' THEN
      RAISE EXCEPTION '%', CASE v_session WHEN 'impersonation'
          THEN 'Supplier bank details cannot be verified while impersonating another user. End the impersonation and act as yourself.'
          ELSE 'Supplier bank details can only be verified by a person signed in as themselves.' END
        USING ERRCODE = 'RB012', DETAIL = v_session;
    END IF;
    v_verifier := public.approval_enforcement_bank_verifier_role(p_company_id);
  END IF;
  IF v_bank_rule THEN
    -- A person in their own session, on and off alike (bankControlRefusal assertHumanSession).
    v_session := public.approval_request_session_actor();
    IF v_session <> 'self' THEN
      RAISE EXCEPTION '%', CASE v_session WHEN 'impersonation'
          THEN 'You cannot switch bank-rule approval ' || CASE WHEN p_enabled THEN 'on' ELSE 'off' END
               || ' while impersonating another user. End the impersonation and act as yourself.'
          ELSE 'Only a person signed in as themselves can switch bank-rule approval ' || CASE WHEN p_enabled THEN 'on' ELSE 'off' END
               || '; an agent or a job cannot.' END
        USING ERRCODE = 'RB012', DETAIL = v_session;
    END IF;
    -- bankRuleApproverRole: the strictest active manual_journal rule's role, never below admin (877).
    v_approver := public.bank_rule_approver_role(p_company_id);
  END IF;

  IF p_enabled THEN
    IF v_bank THEN
      -- ownCompanyRole: the switcher's own role while a member in good standing.
      SELECT cu.role::pg_catalog.text INTO v_own
      FROM public.company_users cu JOIN public.users u ON u.id = cu.user_id
      WHERE cu.company_id = p_company_id AND cu.user_id = p_actor
        AND u.is_active IS TRUE AND u.suspended_at IS NULL
        AND (u.status IS NULL OR pg_catalog.lower(u.status) = 'active');
      IF v_own IS NULL OR public.approval_actor_rank(v_own) < public.approval_required_rank(v_verifier) THEN
        RAISE EXCEPTION 'Switching supplier bank verification on accepts every supplier''s current bank details as verified, so it needs the % role or above — the role that verifies them.', v_verifier
          USING ERRCODE = 'RB013', DETAIL = v_verifier;
      END IF;
    END IF;
    IF v_bank_rule THEN
      -- ownCompanyRole, as for supplier bank details: the switcher's own role while in good standing.
      SELECT cu.role::pg_catalog.text INTO v_own
      FROM public.company_users cu JOIN public.users u ON u.id = cu.user_id
      WHERE cu.company_id = p_company_id AND cu.user_id = p_actor
        AND u.is_active IS TRUE AND u.suspended_at IS NULL
        AND (u.status IS NULL OR pg_catalog.lower(u.status) = 'active');
      IF v_own IS NULL OR public.approval_actor_rank(v_own) < public.approval_required_rank(v_approver) THEN
        RAISE EXCEPTION 'Switching bank-rule approval on needs the % role or above — the role that approves bank-rule changes.', v_approver
          USING ERRCODE = 'RB014', DETAIL = v_approver;
      END IF;
      -- bankRuleAutoPostLock, EXCLUSIVE, before the row: enabled_at is a cutoff
      -- for switching auto-post on, so no rule change records across it (877, R3-1).
      PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('bank_rule_auto_post:' || p_company_id::pg_catalog.text, 0));
    END IF;
    FOREACH v_type IN ARRAY v_types LOOP
      INSERT INTO public.approval_enforcement AS e (company_id, document_type, enabled_by)
      VALUES (p_company_id, v_type, p_actor)
      ON CONFLICT ON CONSTRAINT approval_enforcement_company_type_uq DO NOTHING
      RETURNING e.* INTO v_row;
      CONTINUE WHEN v_row.id IS NULL;
      v_baseline := CASE WHEN v_bank THEN public.approval_enforcement_bank_baseline(p_company_id, p_actor) END;
      v_extra := CASE WHEN v_bank THEN pg_catalog.jsonb_build_object('baselineSuppliers', v_baseline::pg_catalog.text)
                      ELSE '{}'::pg_catalog.jsonb END;
      INSERT INTO public.audit_log (company_id, user_id, user_email, action, entity_type, entity_id, entity_ref, changes)
      VALUES (p_company_id, p_actor, public.approval_rule_actor_email(), 'create', 'approval_enforcement', v_row.id, v_row.document_type,
              pg_catalog.jsonb_build_object('fields', '[]'::pg_catalog.jsonb, 'metadata',
                pg_catalog.jsonb_build_object('actorRole', v_role, 'enforcementId', v_row.id::pg_catalog.text) || v_extra));
      id := v_row.id; document_type := v_row.document_type; enabled_at := v_row.enabled_at; enabled_by := v_row.enabled_by;
      baseline_suppliers := v_baseline;
      RETURN NEXT;
      v_row := NULL;
    END LOOP;
    RETURN;
  END IF;

  -- Off: the authority to weaken the strictest active rule of ANY coupled
  -- type — or, for the bank control, the verifier role.
  IF v_bank THEN
    v_strictest := v_verifier;
  ELSIF v_bank_rule THEN
    v_strictest := v_approver;
  ELSE
    FOREACH v_type IN ARRAY v_types LOOP
      v_rule_role := public.approval_enforcement_strictest_role(p_company_id, v_type);
      IF v_rule_role IS NOT NULL AND (v_strictest IS NULL
          OR public.approval_required_rank(v_rule_role) > public.approval_required_rank(v_strictest)) THEN
        v_strictest := v_rule_role;
      END IF;
    END LOOP;
  END IF;
  IF v_strictest IS NOT NULL AND NOT public.approval_rule_may_weaken(v_role, v_strictest) THEN
    RAISE EXCEPTION '%', CASE WHEN v_bank
        THEN 'Switching supplier bank verification off lets unverified bank details be paid. Bank details are verified at the '
             || v_strictest || ' level, so only a role above ' || v_strictest || ' (or the owner, at owner level) may switch it off'
        WHEN v_bank_rule
        THEN 'Switching bank-rule approval off lets a rule that posts money change with nobody approving it. Bank-rule changes '
             || 'are approved at the ' || v_strictest || ' level, so only a role above ' || v_strictest
             || ' (or the owner, at owner level) may switch it off'
        ELSE 'Switching ' || p_document_type || ' approval enforcement off weakens an active ' || v_strictest
             || '-level rule: only a role above ' || v_strictest || ' (or the owner, for an owner-level rule) may do it' END
      USING ERRCODE = 'RB011', DETAIL = v_strictest;
  END IF;
  FOREACH v_type IN ARRAY v_types LOOP
    DELETE FROM public.approval_enforcement e WHERE e.company_id = p_company_id AND e.document_type = v_type
    RETURNING e.* INTO v_row;
    CONTINUE WHEN v_row.id IS NULL;
    INSERT INTO public.audit_log (company_id, user_id, user_email, action, entity_type, entity_id, entity_ref, changes)
    VALUES (p_company_id, p_actor, public.approval_rule_actor_email(), 'delete', 'approval_enforcement', v_row.id, v_row.document_type,
            pg_catalog.jsonb_build_object('fields', '[]'::pg_catalog.jsonb, 'metadata',
              pg_catalog.jsonb_build_object('actorRole', v_role, 'enforcementId', v_row.id::pg_catalog.text)
              || CASE WHEN v_strictest IS NOT NULL THEN pg_catalog.jsonb_build_object('strictestRuleRole', v_strictest)
                      ELSE '{}'::pg_catalog.jsonb END));
    id := v_row.id; document_type := v_row.document_type; enabled_at := v_row.enabled_at; enabled_by := v_row.enabled_by;
    baseline_suppliers := NULL;
    RETURN NEXT;
    v_row := NULL;
  END LOOP;
END
$$;


ALTER FUNCTION public.approval_enforcement_set(p_company_id uuid, p_document_type text, p_enabled boolean, p_actor text) OWNER TO postgres;

--
-- Name: approval_enforcement_strictest_role(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.approval_enforcement_strictest_role(p_company_id uuid, p_document_type text) RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
  SELECT COALESCE(r.approver_role, 'admin') FROM public.approval_rules r
  WHERE r.company_id = p_company_id AND r.document_type = p_document_type AND r.is_active = true
  ORDER BY public.approval_required_rank(COALESCE(r.approver_role, 'admin')) DESC
  LIMIT 1
$$;


ALTER FUNCTION public.approval_enforcement_strictest_role(p_company_id uuid, p_document_type text) OWNER TO postgres;

--
-- Name: approval_manual_journal_gate_amount(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.approval_manual_journal_gate_amount(p_company_id uuid, p_entry_id uuid) RETURNS numeric
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
  SELECT GREATEST(COALESCE(SUM(ABS(jl.debit)), 0), COALESCE(SUM(ABS(jl.credit)), 0))
  FROM public.gl_journal_lines jl
  JOIN public.gl_journal_entries je ON je.id = jl.journal_entry_id
  WHERE jl.journal_entry_id = p_entry_id AND je.company_id = p_company_id
$$;


ALTER FUNCTION public.approval_manual_journal_gate_amount(p_company_id uuid, p_entry_id uuid) OWNER TO postgres;

--
-- Name: approval_payment_batch_gate_amount(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.approval_payment_batch_gate_amount(p_company_id uuid, p_batch_id uuid) RETURNS numeric
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
  SELECT GREATEST(
    ABS(COALESCE((SELECT b.total_amount FROM public.supplier_payment_batches b
                  WHERE b.id = p_batch_id AND b.company_id = p_company_id), 0)),
    ABS(COALESCE((SELECT SUM(sp.total_amount) FROM public.supplier_payments sp
                  WHERE sp.batch_id = p_batch_id AND sp.company_id = p_company_id), 0)))
$$;


ALTER FUNCTION public.approval_payment_batch_gate_amount(p_company_id uuid, p_batch_id uuid) OWNER TO postgres;

--
-- Name: approval_payment_batch_strictest_rank(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.approval_payment_batch_strictest_rank(p_company_id uuid, p_batch_id uuid) RETURNS integer
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
  SELECT GREATEST(
    public.approval_rule_strictest_rank(p_company_id, 'payment_batch',
      public.approval_payment_batch_gate_amount(p_company_id, p_batch_id)),
    (SELECT MAX(public.approval_rule_strictest_rank(p_company_id, 'supplier_payment', m.amount))
     FROM (SELECT DISTINCT public.approval_supplier_payment_gate_amount(sp.total_amount) AS amount
           FROM public.supplier_payments sp
           WHERE sp.batch_id = p_batch_id AND sp.company_id = p_company_id) m))
$$;


ALTER FUNCTION public.approval_payment_batch_strictest_rank(p_company_id uuid, p_batch_id uuid) OWNER TO postgres;

--
-- Name: approval_request_assert_caller(uuid, text, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.approval_request_assert_caller(p_company_id uuid, p_actor text, p_allow_bypass boolean) RETURNS void
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
BEGIN
  IF p_allow_bypass AND public.approval_request_caller_bypasses() THEN
    RETURN;
  END IF;
  IF p_actor IS NULL OR public.approval_request_subject() IS NULL
     OR p_actor !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
     OR public.approval_request_subject() IS DISTINCT FROM p_actor::pg_catalog.uuid THEN
    RAISE EXCEPTION 'R035_APPROVAL_REQUEST_FORGED: an approval request may only be written by the session''s own user'
      USING ERRCODE = 'RA009';
  END IF;
  IF app.current_company_id() IS DISTINCT FROM p_company_id THEN
    RAISE EXCEPTION 'R035_APPROVAL_REQUEST_FORGED: an approval request may only be written for the request''s own company'
      USING ERRCODE = 'RA009';
  END IF;
END
$_$;


ALTER FUNCTION public.approval_request_assert_caller(p_company_id uuid, p_actor text, p_allow_bypass boolean) OWNER TO postgres;

--
-- Name: approval_request_assert_write_role(uuid, text, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.approval_request_assert_write_role(p_company_id uuid, p_actor text, p_allow_bypass boolean) RETURNS void
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
DECLARE
  v_role pg_catalog.text;
BEGIN
  IF p_allow_bypass AND public.approval_request_caller_bypasses() THEN
    RETURN;
  END IF;
  SELECT cu.role::pg_catalog.text INTO v_role FROM public.company_users cu
  WHERE cu.company_id = p_company_id AND cu.user_id = p_actor;
  IF NOT public.approval_request_may_write(v_role) THEN
    RAISE EXCEPTION 'Your role (%) does not allow this action.', COALESCE(v_role, 'none') USING ERRCODE = 'RA008';
  END IF;
END
$$;


ALTER FUNCTION public.approval_request_assert_write_role(p_company_id uuid, p_actor text, p_allow_bypass boolean) OWNER TO postgres;

SET default_tablespace = '';

SET default_table_access_method = heap;

--
-- Name: approval_rules; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.approval_rules (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    name text NOT NULL,
    document_type text NOT NULL,
    condition_field text DEFAULT 'total'::text NOT NULL,
    condition_operator text DEFAULT 'greater_than'::text NOT NULL,
    condition_value numeric(15,2) DEFAULT 0,
    approver_role text DEFAULT 'admin'::text NOT NULL,
    is_active boolean DEFAULT true,
    priority integer DEFAULT 100,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    company_id uuid
);

ALTER TABLE ONLY public.approval_rules FORCE ROW LEVEL SECURITY;


ALTER TABLE public.approval_rules OWNER TO postgres;

--
-- Name: approval_request_bindable_rule(uuid, text, uuid, numeric, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.approval_request_bindable_rule(p_company_id uuid, p_document_type text, p_document_id uuid, p_amount numeric, p_rule_id uuid) RETURNS public.approval_rules
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
DECLARE
  v_rule public.approval_rules;
  v_strictest pg_catalog.int4;
BEGIN
  SELECT r.* INTO v_rule FROM public.approval_rules r
  WHERE r.id = p_rule_id AND r.company_id = p_company_id AND r.is_active = true;
  IF NOT FOUND THEN
    RETURN NULL;
  END IF;
  v_strictest := CASE WHEN p_document_type = 'payment_batch'
                      THEN public.approval_payment_batch_strictest_rank(p_company_id, p_document_id)
                      ELSE public.approval_rule_strictest_rank(p_company_id, p_document_type, p_amount) END;
  IF v_strictest IS NULL THEN
    RAISE EXCEPTION 'No active approval rule requires approval for % %', p_document_type, p_document_id
      USING ERRCODE = 'RA007';
  END IF;
  IF NOT (v_rule.document_type = p_document_type
          OR (p_document_type = 'payment_batch' AND v_rule.document_type = 'supplier_payment')) THEN
    RAISE EXCEPTION 'R035_APPROVAL_REQUEST_FORGED: a request must be bound to a rule of its document''s type'
      USING ERRCODE = 'RA009';
  END IF;
  -- Not the strictest NOW: a rule was added or edited, or the amount moved,
  -- since the TypeScript chose it (or a caller chose a laxer one) — refused,
  -- and retryable: requestApproval re-reads and raises again.
  IF public.approval_required_rank(v_rule.approver_role) <> v_strictest THEN
    RAISE EXCEPTION 'R035_APPROVAL_REQUEST_STALE: the document or its approval rules changed while the request was being raised'
      USING ERRCODE = 'RA010';
  END IF;
  RETURN v_rule;
END
$$;


ALTER FUNCTION public.approval_request_bindable_rule(p_company_id uuid, p_document_type text, p_document_id uuid, p_amount numeric, p_rule_id uuid) OWNER TO postgres;

--
-- Name: approval_request_caller_bypasses(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.approval_request_caller_bypasses() RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM pg_catalog.pg_roles r
    WHERE r.rolname = CASE pg_catalog.current_setting('role')
                        WHEN 'none' THEN session_user::pg_catalog.text
                        ELSE pg_catalog.current_setting('role') END
      AND (r.rolbypassrls OR r.rolsuper))
$$;


ALTER FUNCTION public.approval_request_caller_bypasses() OWNER TO postgres;

--
-- Name: approval_request_caller_sees(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.approval_request_caller_sees(p_company_id uuid) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
  SELECT public.approval_request_caller_bypasses() OR EXISTS (
    SELECT 1 FROM public.company_users cu
    WHERE cu.company_id = p_company_id AND pg_catalog.lower(cu.user_id) = pg_catalog.lower(auth.uid()))
$$;


ALTER FUNCTION public.approval_request_caller_sees(p_company_id uuid) OWNER TO postgres;

--
-- Name: approval_requests; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.approval_requests (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    rule_id uuid,
    document_type text NOT NULL,
    document_id uuid NOT NULL,
    document_reference text,
    amount numeric(15,2),
    status text DEFAULT 'pending'::text NOT NULL,
    requested_by uuid NOT NULL,
    requested_at timestamp with time zone DEFAULT now(),
    decided_by uuid,
    decided_at timestamp with time zone,
    decision_notes text,
    created_at timestamp with time zone DEFAULT now(),
    company_id uuid,
    document_digest text,
    approver_roster jsonb,
    past_requesters uuid[] DEFAULT '{}'::uuid[] NOT NULL,
    required_role text,
    content_authors uuid[]
);

ALTER TABLE ONLY public.approval_requests FORCE ROW LEVEL SECURITY;


ALTER TABLE public.approval_requests OWNER TO postgres;

--
-- Name: approval_request_decide(uuid, uuid, text, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.approval_request_decide(p_company_id uuid, p_request_id uuid, p_decision text, p_decided_by text, p_notes text, p_expected_digest text) RETURNS SETOF public.approval_requests
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor pg_catalog.text := public.approval_request_session_actor();
  v_row public.approval_requests;
  v_is_self pg_catalog.bool;
  v_rule_id pg_catalog.uuid;
  v_rule_role pg_catalog.text;
  v_demanded pg_catalog.text;
  v_decider_role pg_catalog.text;
  v_enforced pg_catalog.bool;
  v_live_authors pg_catalog.text[];
  v_doc record;
  v_expected pg_catalog.text := NULLIF(p_expected_digest, '');
BEGIN
  -- assertDecidingSession: a Login-as session, or one that cannot be ruled
  -- out as one, decides nothing — approve or reject.
  IF v_actor <> 'self' THEN
    RAISE EXCEPTION '%', CASE v_actor
      WHEN 'impersonation' THEN 'Approval decisions cannot be made while impersonating another user. End the impersonation and decide as yourself.'
      ELSE 'Approval decisions are refused: this session cannot confirm it is not an impersonation.' END
      USING ERRCODE = 'RA003';
  END IF;
  IF p_decision IS NULL OR p_decision NOT IN ('approved', 'rejected') THEN
    RAISE EXCEPTION 'R035_APPROVAL_REQUEST_FORGED: a decision is approved or rejected' USING ERRCODE = 'RA009';
  END IF;
  PERFORM public.approval_request_assert_caller(p_company_id, p_decided_by, false);
  IF NOT public.approval_request_caller_sees(p_company_id) THEN
    RETURN;
  END IF;
  -- withWriteAccess gates approve AND reject (a withdrawal included).
  PERFORM public.approval_request_assert_write_role(p_company_id, p_decided_by, false);

  SELECT ar.* INTO v_row FROM public.approval_requests ar
  WHERE ar.id = p_request_id AND ar.company_id = p_company_id AND ar.status = 'pending'
  FOR UPDATE;
  IF NOT FOUND THEN
    RETURN;
  END IF;
  v_is_self := v_row.requested_by::pg_catalog.text = p_decided_by;

  -- Rejecting your own request is a withdrawal: no authority needed.
  IF NOT (v_is_self AND p_decision = 'rejected') THEN
    SELECT rl.id, rl.approver_role INTO v_rule_id, v_rule_role
    FROM public.approval_rules rl WHERE rl.id = v_row.rule_id AND rl.company_id = p_company_id;
    v_rule_role := COALESCE(v_rule_role, 'admin');
    -- The ratchet (669): the higher of the snapshot and the bound rule's live role.
    v_demanded := CASE WHEN v_row.required_role IS NOT NULL
                         AND public.approval_required_rank(v_row.required_role) > public.approval_required_rank(v_rule_role)
                       THEN v_row.required_role ELSE v_rule_role END;
    SELECT cu.role::pg_catalog.text INTO v_decider_role
    FROM public.company_users cu WHERE cu.company_id = p_company_id AND cu.user_id = p_decided_by;
    v_enforced := EXISTS (SELECT 1 FROM public.approval_enforcement ae
                          WHERE ae.company_id = v_row.company_id AND ae.document_type = v_row.document_type);

    -- contentAuthorRefusal: an author of the content never approves.
    IF p_decision = 'approved' AND NOT v_is_self THEN
      v_live_authors := public.approval_document_authors(v_row.company_id, v_row.document_type, v_row.document_id)::pg_catalog.text[];
      IF v_live_authors IS NULL THEN
        IF p_decided_by = ANY (v_row.past_requesters::pg_catalog.text[]) THEN
          RAISE EXCEPTION 'You cannot approve an approval request you raised for an earlier version of this document'
            USING ERRCODE = 'RA001';
        END IF;
      ELSIF p_decided_by = ANY (v_live_authors || COALESCE(v_row.content_authors::pg_catalog.text[], '{}'::pg_catalog.text[])) THEN
        RAISE EXCEPTION 'You cannot approve this request: you authored the content it covers.' USING ERRCODE = 'RA001';
      END IF;
    END IF;

    -- K-043 with the sole-approver exception (Q2).
    IF v_is_self THEN
      IF v_decider_role IS NULL THEN
        RAISE EXCEPTION 'You cannot approve an approval request you raised yourself while another member can approve it'
          USING ERRCODE = 'RA001';
      END IF;
      IF NOT v_enforced THEN
        RAISE EXCEPTION 'You cannot approve an approval request you raised yourself unless approval enforcement is on for this document type'
          USING ERRCODE = 'RA001';
      END IF;
      IF v_row.approver_roster IS NULL
         OR v_row.approver_roster IS DISTINCT FROM public.approval_roster_snapshot(p_company_id, p_decided_by) THEN
        RAISE EXCEPTION 'You cannot approve an approval request you raised yourself — the company members or roles changed since it was raised'
          USING ERRCODE = 'RA001';
      END IF;
      IF EXISTS (
        SELECT 1 FROM public.approval_company_other_members(p_company_id, p_decided_by) m
        WHERE m.is_active IS TRUE AND m.suspended_at IS NULL
          AND (m.status IS NULL OR pg_catalog.lower(m.status) = 'active')
          AND public.approval_actor_rank(m.role) >= public.approval_required_rank(v_demanded)
      ) THEN
        RAISE EXCEPTION 'You cannot approve an approval request you raised yourself while another member can approve it'
          USING ERRCODE = 'RA001';
      END IF;
    END IF;

    IF v_row.rule_id IS NOT NULL AND v_rule_id IS NULL THEN
      RAISE EXCEPTION 'This approval names a rule that does not belong to this company and cannot be decided'
        USING ERRCODE = 'RA002';
    END IF;
    IF v_decider_role IS NULL THEN
      RAISE EXCEPTION 'You have no role in this company and cannot decide approvals' USING ERRCODE = 'RA002';
    END IF;
    IF public.approval_actor_rank(v_decider_role) < public.approval_required_rank(v_demanded) THEN
      RAISE EXCEPTION 'This approval requires the % role', v_demanded USING ERRCODE = 'RA002';
    END IF;
  END IF;

  -- assertDocumentUnchanged: the document exists, and the digest the approver
  -- was shown, the one raised for and the live one all agree.
  IF p_decision = 'approved' THEN
    SELECT f.* INTO v_doc FROM public.approval_request_document_facts(p_company_id, v_row.document_type, v_row.document_id) f;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'No % % exists for this company', v_row.document_type, v_row.document_id USING ERRCODE = 'RA006';
    END IF;
    IF v_row.document_digest IS NOT NULL AND v_expected IS NULL THEN
      RAISE EXCEPTION 'Approving request % requires expectedDigest — the document digest you were shown.', p_request_id
        USING ERRCODE = 'RA005';
    END IF;
    IF v_expected IS DISTINCT FROM v_row.document_digest OR v_row.document_digest IS DISTINCT FROM v_doc.digest THEN
      RAISE EXCEPTION 'The document changed after approval request % was raised. Submit it for approval again.', p_request_id
        USING ERRCODE = 'RA004';
    END IF;
  END IF;

  UPDATE public.approval_requests ar SET
    status = p_decision,
    decided_by = p_decided_by::pg_catalog.uuid,
    decided_at = pg_catalog.now(),
    decision_notes = p_notes
  WHERE ar.id = p_request_id AND ar.company_id = p_company_id AND ar.status = 'pending'
  RETURNING ar.* INTO v_row;
  IF NOT FOUND THEN
    RETURN;
  END IF;
  IF v_is_self AND p_decision = 'approved' THEN
    INSERT INTO public.audit_log (company_id, user_id, action, entity_type, entity_id, entity_ref, changes)
    VALUES (p_company_id, p_decided_by, 'approve', 'approval_request', v_row.id, v_row.document_reference,
      pg_catalog.jsonb_build_object('fields', '[]'::pg_catalog.jsonb, 'metadata',
        pg_catalog.jsonb_build_object(
          'selfApproval', 'sole_approver', 'requiredRole', v_demanded,
          'approverRoster', COALESCE(v_row.approver_roster::pg_catalog.text, 'null'),
          'documentType', v_row.document_type, 'documentId', v_row.document_id::pg_catalog.text)
        || CASE WHEN v_row.document_digest IS NOT NULL
                THEN pg_catalog.jsonb_build_object('documentDigest', v_row.document_digest)
                ELSE '{}'::pg_catalog.jsonb END));
  END IF;
  RETURN NEXT v_row;
END
$$;


ALTER FUNCTION public.approval_request_decide(p_company_id uuid, p_request_id uuid, p_decision text, p_decided_by text, p_notes text, p_expected_digest text) OWNER TO postgres;

--
-- Name: approval_request_document_facts(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.approval_request_document_facts(p_company_id uuid, p_document_type text, p_document_id uuid) RETURNS TABLE(amount numeric, reference text, digest text)
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
BEGIN
  CASE p_document_type
    WHEN 'customer_invoice' THEN
      RETURN QUERY SELECT public.approval_customer_invoice_gate_amount(d.total_amount, d.functional_total),
             d.invoice_number::pg_catalog.text, public.approval_document_digest(d.company_id, 'customer_invoice', d.id)
      FROM public.customer_invoices d
      WHERE d.id = p_document_id AND d.company_id = p_company_id AND d.deleted_at IS NULL;
    WHEN 'supplier_invoice' THEN
      RETURN QUERY SELECT public.approval_supplier_invoice_gate_amount(d.total_amount, d.functional_total),
             d.invoice_number::pg_catalog.text, public.approval_document_digest(d.company_id, 'supplier_invoice', d.id)
      FROM public.supplier_invoices d
      WHERE d.id = p_document_id AND d.company_id = p_company_id AND d.deleted_at IS NULL;
    WHEN 'credit_note' THEN
      RETURN QUERY SELECT COALESCE(d.total_amount, 0)::pg_catalog.numeric, d.credit_note_number::pg_catalog.text,
             public.approval_document_digest(d.company_id, 'credit_note', d.id)
      FROM public.credit_notes d WHERE d.id = p_document_id AND d.company_id = p_company_id;
    WHEN 'customer_credit_note' THEN
      RETURN QUERY SELECT public.approval_credit_note_gate_amount(d.total_amount, d.subtotal, d.tax_amount),
             d.credit_note_number::pg_catalog.text, public.approval_document_digest(d.company_id, 'customer_credit_note', d.id)
      FROM public.credit_notes d WHERE d.id = p_document_id AND d.company_id = p_company_id AND d.type = 'customer';
    WHEN 'supplier_credit_note' THEN
      RETURN QUERY SELECT public.approval_credit_note_gate_amount(d.total_amount, d.subtotal, d.tax_amount),
             d.credit_note_number::pg_catalog.text, public.approval_document_digest(d.company_id, 'supplier_credit_note', d.id)
      FROM public.credit_notes d WHERE d.id = p_document_id AND d.company_id = p_company_id AND d.type = 'supplier';
    WHEN 'supplier_payment' THEN
      RETURN QUERY SELECT public.approval_supplier_payment_gate_amount(d.total_amount), d.payment_number::pg_catalog.text,
             public.approval_document_digest(d.company_id, 'supplier_payment', d.id)
      FROM public.supplier_payments d
      WHERE d.id = p_document_id AND d.company_id = p_company_id AND d.batch_id IS NULL;
    WHEN 'payment_batch' THEN
      RETURN QUERY SELECT public.approval_payment_batch_gate_amount(d.company_id, d.id), d.batch_number::pg_catalog.text,
             public.approval_document_digest(d.company_id, 'payment_batch', d.id)
      FROM public.supplier_payment_batches d WHERE d.id = p_document_id AND d.company_id = p_company_id;
    WHEN 'payment' THEN
      RETURN QUERY SELECT COALESCE(d.total_amount, 0)::pg_catalog.numeric, d.payment_number::pg_catalog.text,
             public.approval_document_digest(d.company_id, 'payment', d.id)
      FROM public.customer_payments d WHERE d.id = p_document_id AND d.company_id = p_company_id;
      IF NOT FOUND THEN
        RETURN QUERY SELECT COALESCE(d.total_amount, 0)::pg_catalog.numeric, d.payment_number::pg_catalog.text,
               public.approval_document_digest(d.company_id, 'payment', d.id)
        FROM public.supplier_payments d WHERE d.id = p_document_id AND d.company_id = p_company_id;
      END IF;
    WHEN 'manual_journal' THEN
      RETURN QUERY SELECT public.approval_manual_journal_gate_amount(d.company_id, d.id), d.entry_number::pg_catalog.text,
             public.approval_document_digest(d.company_id, 'manual_journal', d.id)
      FROM public.gl_journal_entries d WHERE d.id = p_document_id AND d.company_id = p_company_id;
    WHEN 'journal_entry' THEN
      RETURN QUERY SELECT COALESCE((
               SELECT SUM(jl.debit) FROM public.gl_journal_lines jl
               WHERE jl.journal_entry_id = je.id AND jl.company_id = p_company_id), 0)::pg_catalog.numeric,
             je.entry_number::pg_catalog.text, public.approval_document_digest(je.company_id, 'journal_entry', je.id)
      FROM public.gl_journal_entries je WHERE je.id = p_document_id AND je.company_id = p_company_id;
    ELSE
      RETURN;
  END CASE;
END
$$;


ALTER FUNCTION public.approval_request_document_facts(p_company_id uuid, p_document_type text, p_document_id uuid) OWNER TO postgres;

--
-- Name: approval_request_insert_guard(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.approval_request_insert_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
DECLARE
  v_subject pg_catalog.text;
  v_uid pg_catalog.uuid;
BEGIN
  IF NOT (NEW.document_type = ANY (ARRAY['customer_credit_note', 'supplier_credit_note', 'customer_invoice',
                                         'supplier_payment', 'payment_batch', 'manual_journal']::pg_catalog.text[]))
     OR EXISTS (
       SELECT 1 FROM pg_catalog.pg_roles r
       WHERE r.rolname = current_user AND (r.rolbypassrls OR r.rolsuper)) THEN
    RETURN NEW;
  END IF;
  -- Only a canonical uuid is cast (any case); anything else leaves v_uid NULL,
  -- which no requested_by (NOT NULL) equals: a refusal, never a cast error.
  v_subject := auth.uid();
  IF v_subject ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    v_uid := v_subject::pg_catalog.uuid;
  END IF;
  IF COALESCE(NEW.status, '') <> 'pending'
     OR NEW.requested_by IS DISTINCT FROM v_uid
     OR NEW.decided_by IS NOT NULL
     OR NEW.decided_at IS NOT NULL
     OR pg_catalog.cardinality(COALESCE(NEW.past_requesters, '{}')) > 0 THEN
    RAISE EXCEPTION 'R035_APPROVAL_REQUEST_FORGED: a % approval request may only be inserted pending, undecided and raised by the session''s own user', NEW.document_type
      USING HINT = 'Raise the request through IsaFlow, then have an eligible approver decide it.';
  END IF;
  RETURN NEW;
END
$_$;


ALTER FUNCTION public.approval_request_insert_guard() OWNER TO postgres;

--
-- Name: approval_request_lock(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.approval_request_lock(p_company_id uuid, p_request_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
BEGIN
  IF NOT public.approval_request_caller_bypasses() AND app.current_company_id() IS DISTINCT FROM p_company_id THEN
    RAISE EXCEPTION 'R035_APPROVAL_REQUEST_FORGED: a request may only be locked for the request''s own company'
      USING ERRCODE = 'RA009';
  END IF;
  IF NOT public.approval_request_caller_sees(p_company_id) THEN
    RETURN;
  END IF;
  PERFORM public.approval_request_assert_write_role(p_company_id, auth.uid(), true);
  PERFORM 1 FROM public.approval_requests ar
  WHERE ar.id = p_request_id AND ar.company_id = p_company_id AND ar.status = 'pending'
  FOR UPDATE;
END
$$;


ALTER FUNCTION public.approval_request_lock(p_company_id uuid, p_request_id uuid) OWNER TO postgres;

--
-- Name: approval_request_may_write(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.approval_request_may_write(p_role text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
  SELECT COALESCE(p_role = ANY (ARRAY['owner', 'admin', 'manager']::pg_catalog.text[]), false)
$$;


ALTER FUNCTION public.approval_request_may_write(p_role text) OWNER TO postgres;

--
-- Name: approval_request_raise(uuid, text, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.approval_request_raise(p_company_id uuid, p_document_type text, p_document_id uuid, p_rule_id uuid, p_requested_by text) RETURNS SETOF public.approval_requests
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
DECLARE
  v_doc record;
  v_rule public.approval_rules;
BEGIN
  IF public.approval_request_session_actor() = 'impersonation' THEN
    RAISE EXCEPTION 'This action cannot be taken while impersonating another user. End the impersonation and act as yourself.'
      USING ERRCODE = 'RA003';
  END IF;
  PERFORM public.approval_request_assert_caller(p_company_id, p_requested_by, true);
  SELECT f.* INTO v_doc FROM public.approval_request_document_facts(p_company_id, p_document_type, p_document_id) f
  WHERE public.approval_request_caller_sees(p_company_id);
  IF NOT FOUND THEN
    RAISE EXCEPTION 'No % % exists for this company', p_document_type, p_document_id USING ERRCODE = 'RA006';
  END IF;
  PERFORM public.approval_request_assert_write_role(p_company_id, p_requested_by, true);
  v_rule := public.approval_request_bindable_rule(p_company_id, p_document_type, p_document_id, v_doc.amount, p_rule_id);
  IF v_rule.id IS NULL THEN
    RETURN;
  END IF;
  RETURN QUERY
    INSERT INTO public.approval_requests (company_id, rule_id, document_type, document_id, document_reference, amount,
      requested_by, required_role, document_digest, content_authors, approver_roster)
    VALUES (p_company_id, v_rule.id, p_document_type, p_document_id, v_doc.reference, v_doc.amount,
      p_requested_by::pg_catalog.uuid, v_rule.approver_role, v_doc.digest,
      public.approval_document_authors(p_company_id, p_document_type, p_document_id),
      (SELECT public.approval_roster_snapshot(p_company_id, p_requested_by)
       WHERE EXISTS (SELECT 1 FROM public.approval_enforcement ae
                     WHERE ae.company_id = p_company_id AND ae.document_type = p_document_type)))
    RETURNING *;
END
$$;


ALTER FUNCTION public.approval_request_raise(p_company_id uuid, p_document_type text, p_document_id uuid, p_rule_id uuid, p_requested_by text) OWNER TO postgres;

--
-- Name: approval_request_rebind(uuid, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.approval_request_rebind(p_company_id uuid, p_request_id uuid, p_rule_id uuid, p_requested_by text) RETURNS SETOF public.approval_requests
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
DECLARE
  v_row public.approval_requests;
  v_doc record;
  v_rule public.approval_rules;
  v_current pg_catalog.text;
  v_changed pg_catalog.bool;
BEGIN
  IF public.approval_request_session_actor() = 'impersonation' THEN
    RAISE EXCEPTION 'This action cannot be taken while impersonating another user. End the impersonation and act as yourself.'
      USING ERRCODE = 'RA003';
  END IF;
  PERFORM public.approval_request_assert_caller(p_company_id, p_requested_by, true);
  IF NOT public.approval_request_caller_sees(p_company_id) THEN
    RETURN;
  END IF;
  PERFORM public.approval_request_assert_write_role(p_company_id, p_requested_by, true);
  SELECT ar.* INTO v_row FROM public.approval_requests ar
  WHERE ar.id = p_request_id AND ar.company_id = p_company_id AND ar.status = 'pending'
  FOR UPDATE;
  IF NOT FOUND THEN
    RETURN;
  END IF;
  SELECT f.* INTO v_doc FROM public.approval_request_document_facts(p_company_id, v_row.document_type, v_row.document_id) f;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'No % % exists for this company', v_row.document_type, v_row.document_id USING ERRCODE = 'RA006';
  END IF;
  IF p_rule_id IS NOT NULL THEN
    -- A rule deactivated since the TypeScript chose it binds nothing: the
    -- request keeps its binding and its content is still re-stamped, as the
    -- direct UPDATE did (COALESCE below keeps rule_id and required_role).
    v_rule := public.approval_request_bindable_rule(p_company_id, v_row.document_type, v_row.document_id, v_doc.amount, p_rule_id);
  END IF;
  IF v_rule.id IS NOT NULL THEN
    SELECT COALESCE(v_row.required_role, rl.approver_role, 'admin') INTO v_current
    FROM (SELECT 1) one
    LEFT JOIN public.approval_rules rl ON rl.id = v_row.rule_id AND rl.company_id = v_row.company_id;
    IF public.approval_required_rank(v_rule.approver_role) < public.approval_required_rank(v_current) THEN
      RAISE EXCEPTION 'R035_APPROVAL_REQUEST_FORGED: a pending request may only be re-bound to a stricter rule'
        USING ERRCODE = 'RA009';
    END IF;
  END IF;
  v_changed := v_row.document_digest IS DISTINCT FROM v_doc.digest;
  RETURN QUERY
    UPDATE public.approval_requests ar SET
      rule_id = COALESCE(v_rule.id, ar.rule_id),
      required_role = COALESCE(v_rule.approver_role, ar.required_role),
      amount = v_doc.amount,
      document_reference = v_doc.reference,
      document_digest = v_doc.digest,
      content_authors = CASE WHEN v_changed
                             THEN public.approval_document_authors(ar.company_id, ar.document_type, ar.document_id)
                             ELSE ar.content_authors END,
      past_requesters = CASE WHEN v_changed AND ar.requested_by <> p_requested_by::pg_catalog.uuid
                             THEN pg_catalog.array_append(ar.past_requesters, ar.requested_by) ELSE ar.past_requesters END,
      requested_by = CASE WHEN v_changed THEN p_requested_by::pg_catalog.uuid ELSE ar.requested_by END,
      requested_at = CASE WHEN v_changed THEN pg_catalog.now() ELSE ar.requested_at END,
      approver_roster = CASE WHEN v_changed THEN (
        SELECT public.approval_roster_snapshot(p_company_id, p_requested_by)
        WHERE EXISTS (SELECT 1 FROM public.approval_enforcement ae
                      WHERE ae.company_id = p_company_id AND ae.document_type = ar.document_type)
      ) ELSE ar.approver_roster END
    WHERE ar.id = p_request_id AND ar.company_id = p_company_id AND ar.status = 'pending'
    RETURNING ar.*;
END
$$;


ALTER FUNCTION public.approval_request_rebind(p_company_id uuid, p_request_id uuid, p_rule_id uuid, p_requested_by text) OWNER TO postgres;

--
-- Name: approval_request_session_actor(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.approval_request_session_actor() RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
  SELECT CASE
    WHEN c.session_id IS NULL OR c.session_id = '' THEN 'unknown'
    WHEN EXISTS (SELECT 1 FROM public.impersonation_sessions s WHERE s.session_id = c.session_id) THEN 'impersonation'
    ELSE 'self' END
  FROM (SELECT NULLIF(pg_catalog.current_setting('request.jwt.claims', true), '')::pg_catalog.jsonb
                 ->> 'session_id' AS session_id) c
$$;


ALTER FUNCTION public.approval_request_session_actor() OWNER TO postgres;

--
-- Name: approval_request_subject(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.approval_request_subject() RETURNS uuid
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
DECLARE
  v_subject pg_catalog.text := auth.uid();
BEGIN
  IF v_subject ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    RETURN v_subject::pg_catalog.uuid;
  END IF;
  RETURN NULL;
END
$_$;


ALTER FUNCTION public.approval_request_subject() OWNER TO postgres;

--
-- Name: approval_required_rank(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.approval_required_rank(p_role text) RETURNS integer
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
  SELECT CASE p_role
    WHEN 'super_admin' THEN 8 WHEN 'owner' THEN 7 WHEN 'system' THEN 6 WHEN 'admin' THEN 5
    WHEN 'manager' THEN 4 WHEN 'accountant' THEN 3 WHEN 'bookkeeper' THEN 2
    WHEN 'storeman' THEN 1 WHEN 'technician' THEN 1 WHEN 'user' THEN 1 WHEN 'viewer' THEN 0
    ELSE 5
  END
$$;


ALTER FUNCTION public.approval_required_rank(p_role text) OWNER TO postgres;

--
-- Name: approval_roster_snapshot(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.approval_roster_snapshot(p_company_id uuid, p_user_id text) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
  SELECT jsonb_build_object(
    'requester_role', (SELECT cu.role FROM public.company_users cu
                       WHERE cu.company_id = p_company_id AND cu.user_id = p_user_id),
    'others', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
               'user_id', m.user_id, 'role', m.role, 'is_active', m.is_active,
               'status', m.status, 'suspended', m.suspended_at IS NOT NULL) ORDER BY m.user_id)
      FROM public.approval_company_other_members(p_company_id, p_user_id) m
    ), '[]'::jsonb))
$$;


ALTER FUNCTION public.approval_roster_snapshot(p_company_id uuid, p_user_id text) OWNER TO postgres;

--
-- Name: approval_rule_actor_email(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.approval_rule_actor_email() RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
  SELECT CASE WHEN pg_catalog.jsonb_typeof(c -> 'email') = 'string' THEN c ->> 'email' END
  FROM (SELECT NULLIF(pg_catalog.current_setting('request.jwt.claims', true), '')::pg_catalog.jsonb AS c) x
$$;


ALTER FUNCTION public.approval_rule_actor_email() OWNER TO postgres;

--
-- Name: approval_rule_actor_role(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.approval_rule_actor_role(p_company_id uuid, p_actor text) RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
  SELECT cu.role::pg_catalog.text FROM public.company_users cu
  WHERE cu.company_id = p_company_id AND cu.user_id = p_actor
$$;


ALTER FUNCTION public.approval_rule_actor_role(p_company_id uuid, p_actor text) OWNER TO postgres;

--
-- Name: approval_rule_amount_ok(numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.approval_rule_amount_ok(p_value numeric) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
  SELECT p_value IS NOT NULL AND p_value <> 'NaN'::pg_catalog.numeric
     AND p_value >= 0 AND p_value <= 9999999999999.99 AND p_value = pg_catalog.round(p_value, 2)
$$;


ALTER FUNCTION public.approval_rule_amount_ok(p_value numeric) OWNER TO postgres;

--
-- Name: approval_rule_assert_caller(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.approval_rule_assert_caller(p_company_id uuid, p_actor text) RETURNS void
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
BEGIN
  IF p_actor IS NULL OR public.approval_request_subject() IS NULL
     OR p_actor !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
     OR public.approval_request_subject() IS DISTINCT FROM p_actor::pg_catalog.uuid THEN
    RAISE EXCEPTION 'R035_APPROVAL_RULE_FORGED: approval rules and switches may only be written by the session''s own user'
      USING ERRCODE = 'RB020';
  END IF;
  IF app.current_company_id() IS DISTINCT FROM p_company_id THEN
    RAISE EXCEPTION 'R035_APPROVAL_RULE_FORGED: approval rules and switches may only be written for the request''s own company'
      USING ERRCODE = 'RB020';
  END IF;
  -- The routes' gate: withWriteAccess with the default roles (writeRoles.ts).
  PERFORM public.approval_request_assert_write_role(p_company_id, p_actor, false);
END
$_$;


ALTER FUNCTION public.approval_rule_assert_caller(p_company_id uuid, p_actor text) OWNER TO postgres;

--
-- Name: approval_rule_assert_input(text, text, text, text, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.approval_rule_assert_input(p_name text, p_approver_role text, p_operator text, p_field text, p_value numeric) RETURNS void
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
BEGIN
  IF p_name IS NOT NULL AND NOT public.approval_rule_name_ok(p_name) THEN
    RAISE EXCEPTION 'name must be 1 to 100 characters of visible text, with no control characters' USING ERRCODE = 'RB005';
  END IF;
  IF p_approver_role IS NOT NULL AND p_approver_role <> ALL (ARRAY['super_admin', 'owner', 'system', 'admin', 'manager',
       'accountant', 'bookkeeper', 'storeman', 'technician', 'user', 'viewer']::pg_catalog.text[]) THEN
    RAISE EXCEPTION 'approverRole must be one of: super_admin, owner, system, admin, manager, accountant, bookkeeper, storeman, technician, user, viewer (got %)',
      p_approver_role USING ERRCODE = 'RB006', DETAIL = p_approver_role;
  END IF;
  IF p_operator IS NOT NULL AND p_operator <> ALL (ARRAY['any', 'greater_than', 'greater_equal']::pg_catalog.text[]) THEN
    RAISE EXCEPTION 'conditionOperator must be one of: any, greater_than, greater_equal (got %)', p_operator
      USING ERRCODE = 'RB007', DETAIL = p_operator;
  END IF;
  IF p_field IS NOT NULL AND p_field <> ALL (ARRAY['total', 'amount']::pg_catalog.text[]) THEN
    RAISE EXCEPTION 'conditionField must be one of: total, amount (got %)', p_field USING ERRCODE = 'RB008', DETAIL = p_field;
  END IF;
  IF p_value IS NOT NULL AND NOT public.approval_rule_amount_ok(p_value) THEN
    RAISE EXCEPTION 'conditionValue must be a number from 0 to 9999999999999.99 with at most 2 decimals' USING ERRCODE = 'RB009';
  END IF;
END
$$;


ALTER FUNCTION public.approval_rule_assert_input(p_name text, p_approver_role text, p_operator text, p_field text, p_value numeric) OWNER TO postgres;

--
-- Name: approval_rule_assert_may_demand(text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.approval_rule_assert_may_demand(p_actor_role text, p_rule_role text) RETURNS void
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
BEGIN
  IF p_rule_role IS NOT NULL
     AND public.approval_actor_rank(p_actor_role) < public.approval_required_rank(p_rule_role) THEN
    RAISE EXCEPTION 'This rule requires the % role; you do not hold it, so you cannot create, change or delete it', p_rule_role
      USING ERRCODE = 'RB001', DETAIL = p_rule_role;
  END IF;
END
$$;


ALTER FUNCTION public.approval_rule_assert_may_demand(p_actor_role text, p_rule_role text) OWNER TO postgres;

--
-- Name: approval_rule_audit(uuid, text, text, text, uuid, public.approval_rules, public.approval_rules); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.approval_rule_audit(p_company_id uuid, p_actor text, p_actor_role text, p_action text, p_rule_id uuid, p_before public.approval_rules, p_after public.approval_rules) RETURNS void
    LANGUAGE sql
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
  INSERT INTO public.audit_log (company_id, user_id, user_email, action, entity_type, entity_id, entity_ref, changes)
  VALUES (p_company_id, p_actor, public.approval_rule_actor_email(), p_action, 'approval_rule', p_rule_id,
          COALESCE(p_after.name, p_before.name),
          pg_catalog.jsonb_build_object('fields', public.approval_rule_audit_fields(p_before, p_after),
                                        'metadata', pg_catalog.jsonb_build_object('actorRole', p_actor_role)))
$$;


ALTER FUNCTION public.approval_rule_audit(p_company_id uuid, p_actor text, p_actor_role text, p_action text, p_rule_id uuid, p_before public.approval_rules, p_after public.approval_rules) OWNER TO postgres;

--
-- Name: approval_rule_audit_fields(public.approval_rules, public.approval_rules); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.approval_rule_audit_fields(p_before public.approval_rules, p_after public.approval_rules) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
  SELECT COALESCE(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object('field', f.field, 'old', f.old, 'new', f.new, 'label', f.field)
                                       ORDER BY f.ord), '[]'::pg_catalog.jsonb)
  FROM (VALUES
    (1, 'name', p_before.name, p_after.name),
    (2, 'document_type', p_before.document_type, p_after.document_type),
    (3, 'condition_field', p_before.condition_field, p_after.condition_field),
    (4, 'condition_operator', p_before.condition_operator, p_after.condition_operator),
    (5, 'condition_value', p_before.condition_value::pg_catalog.text, p_after.condition_value::pg_catalog.text),
    (6, 'approver_role', p_before.approver_role, p_after.approver_role),
    (7, 'is_active', p_before.is_active::pg_catalog.text, p_after.is_active::pg_catalog.text),
    (8, 'priority', p_before.priority::pg_catalog.text, p_after.priority::pg_catalog.text)
  ) AS f(ord, field, old, new)
  WHERE f.old IS DISTINCT FROM f.new
$$;


ALTER FUNCTION public.approval_rule_audit_fields(p_before public.approval_rules, p_after public.approval_rules) OWNER TO postgres;

--
-- Name: approval_rule_create(uuid, text, text, text, text, text, numeric, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.approval_rule_create(p_company_id uuid, p_actor text, p_name text, p_document_type text, p_condition_field text, p_condition_operator text, p_condition_value numeric, p_approver_role text) RETURNS SETOF public.approval_rules
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
DECLARE
  v_role pg_catalog.text;
  v_row public.approval_rules;
BEGIN
  PERFORM public.approval_rule_assert_caller(p_company_id, p_actor);
  v_role := public.approval_rule_actor_role(p_company_id, p_actor);
  CASE p_document_type
    WHEN 'credit_note' THEN
      RAISE EXCEPTION 'Approval rules of type credit_note no longer govern any credit note. Create a customer_credit_note or supplier_credit_note rule instead.'
        USING ERRCODE = 'RB003', DETAIL = p_document_type;
    WHEN 'payment' THEN
      RAISE EXCEPTION 'Approval rules of type payment no longer govern any supplier payment. Create a supplier_payment or payment_batch rule instead.'
        USING ERRCODE = 'RB003', DETAIL = p_document_type;
    WHEN 'journal_entry' THEN
      RAISE EXCEPTION 'Approval rules of type journal_entry no longer govern any journal. Create a manual_journal rule instead.'
        USING ERRCODE = 'RB003', DETAIL = p_document_type;
    ELSE NULL;
  END CASE;
  IF p_document_type IS NULL OR p_document_type <> ALL (ARRAY['supplier_invoice', 'customer_credit_note', 'supplier_credit_note',
       'customer_invoice', 'supplier_payment', 'payment_batch', 'manual_journal']::pg_catalog.text[]) THEN
    RAISE EXCEPTION 'documentType must be one of: supplier_invoice, customer_credit_note, supplier_credit_note, customer_invoice, supplier_payment, payment_batch, manual_journal'
      USING ERRCODE = 'RB004';
  END IF;
  IF p_name IS NULL THEN
    RAISE EXCEPTION 'name must be 1 to 100 characters of visible text, with no control characters' USING ERRCODE = 'RB005';
  END IF;
  PERFORM public.approval_rule_assert_input(p_name, p_approver_role, p_condition_operator, p_condition_field, p_condition_value);
  PERFORM public.approval_rule_assert_may_demand(v_role, COALESCE(p_approver_role, 'admin'));
  INSERT INTO public.approval_rules (company_id, name, document_type, condition_field, condition_operator, condition_value, approver_role)
  VALUES (p_company_id, public.approval_rule_js_trim(p_name), p_document_type, COALESCE(p_condition_field, 'total'),
          COALESCE(p_condition_operator, 'greater_than'), COALESCE(p_condition_value, 0), COALESCE(p_approver_role, 'admin'))
  RETURNING * INTO v_row;
  PERFORM public.approval_rule_audit(p_company_id, p_actor, v_role, 'create', v_row.id, NULL, v_row);
  RETURN NEXT v_row;
END
$$;


ALTER FUNCTION public.approval_rule_create(p_company_id uuid, p_actor text, p_name text, p_document_type text, p_condition_field text, p_condition_operator text, p_condition_value numeric, p_approver_role text) OWNER TO postgres;

--
-- Name: approval_rule_delete(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.approval_rule_delete(p_company_id uuid, p_rule_id uuid, p_actor text) RETURNS SETOF uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
DECLARE
  v_role pg_catalog.text;
  v_before public.approval_rules;
  v_rule_role pg_catalog.text;
BEGIN
  PERFORM public.approval_rule_assert_caller(p_company_id, p_actor);
  v_role := public.approval_rule_actor_role(p_company_id, p_actor);
  SELECT * INTO v_before FROM public.approval_rules r WHERE r.id = p_rule_id AND r.company_id = p_company_id FOR UPDATE;
  IF NOT FOUND THEN RETURN; END IF;
  v_rule_role := COALESCE(v_before.approver_role, 'admin');
  IF public.approval_actor_rank(v_role) < public.approval_required_rank(v_rule_role) THEN
    RAISE EXCEPTION 'This rule requires the % role; you do not hold it, so you cannot create, change or delete it', v_rule_role
      USING ERRCODE = 'RB001', DETAIL = v_rule_role;
  END IF;
  IF NOT public.approval_rule_may_weaken(v_role, v_rule_role) THEN
    RAISE EXCEPTION 'Only a role above % can lower, deactivate, delete or narrow this %-level rule', v_rule_role, v_rule_role
      USING ERRCODE = 'RB002', DETAIL = v_rule_role;
  END IF;
  DELETE FROM public.approval_rules r WHERE r.id = p_rule_id AND r.company_id = p_company_id;
  PERFORM public.approval_rule_audit(p_company_id, p_actor, v_role, 'delete', p_rule_id, v_before, NULL);
  RETURN NEXT p_rule_id;
END
$$;


ALTER FUNCTION public.approval_rule_delete(p_company_id uuid, p_rule_id uuid, p_actor text) OWNER TO postgres;

--
-- Name: approval_rule_js_trim(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.approval_rule_js_trim(p_text text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
  SELECT pg_catalog.regexp_replace(p_text,
    '^[\u0009-\u000D    -     　﻿]+|[\u0009-\u000D    -     　﻿]+$',
    '', 'g')
$_$;


ALTER FUNCTION public.approval_rule_js_trim(p_text text) OWNER TO postgres;

--
-- Name: approval_rule_lock(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.approval_rule_lock(p_company_id uuid, p_rule_id uuid, p_actor text) RETURNS SETOF public.approval_rules
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
BEGIN
  PERFORM public.approval_rule_assert_caller(p_company_id, p_actor);
  RETURN QUERY SELECT r.* FROM public.approval_rules r WHERE r.id = p_rule_id AND r.company_id = p_company_id FOR UPDATE;
END
$$;


ALTER FUNCTION public.approval_rule_lock(p_company_id uuid, p_rule_id uuid, p_actor text) OWNER TO postgres;

--
-- Name: approval_rule_matches(uuid, text, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.approval_rule_matches(p_company_id uuid, p_document_type text, p_amount numeric) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
  SELECT public.approval_rule_strictest_rank(p_company_id, p_document_type, p_amount) IS NOT NULL
$$;


ALTER FUNCTION public.approval_rule_matches(p_company_id uuid, p_document_type text, p_amount numeric) OWNER TO postgres;

--
-- Name: approval_rule_may_weaken(text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.approval_rule_may_weaken(p_actor_role text, p_rule_role text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
  SELECT CASE WHEN public.approval_required_rank(p_rule_role) = 7
              THEN public.approval_actor_rank(p_actor_role) >= public.approval_required_rank(p_rule_role)
              ELSE public.approval_actor_rank(p_actor_role) > public.approval_required_rank(p_rule_role) END
$$;


ALTER FUNCTION public.approval_rule_may_weaken(p_actor_role text, p_rule_role text) OWNER TO postgres;

--
-- Name: approval_rule_name_ok(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.approval_rule_name_ok(p_name text) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
DECLARE
  v pg_catalog.text := public.approval_rule_js_trim(p_name);
BEGIN
  IF v IS NULL OR v = '' THEN RETURN false; END IF;
  IF pg_catalog.length(v) + pg_catalog.regexp_count(v, '[\U00010000-\U0010FFFF]') > 100 THEN RETURN false; END IF;
  IF v ~ '[\u0001-\u001F\u007F-\u009F]' THEN RETURN false; END IF;
  RETURN v ~ ('[^\u0009-\u000D    -     　﻿'
           || '\u0001-\u001F\u007F-\u009F'
           || '­؀-؅؜۝܏࢐࢑࣢᠎​-‏‪-‮⁠-⁤⁦-⁯'
           || '￹-￻\U000110BD\U000110CD\U00013430-\U0001343F\U0001BCA0-\U0001BCA3\U0001D173-\U0001D17A\U000E0001\U000E0020-\U000E007F'
           || '̀-ͯ҃-҉᪰-᫿᷀-᷿⃐-⃿︀-️︠-︯\U000E0100-\U000E01EF'
           || 'ᅟᅠㅤﾠ⠀]');
END
$$;


ALTER FUNCTION public.approval_rule_name_ok(p_name text) OWNER TO postgres;

--
-- Name: approval_rule_strictest_rank(uuid, text, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.approval_rule_strictest_rank(p_company_id uuid, p_document_type text, p_amount numeric) RETURNS integer
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
  SELECT MAX(public.approval_required_rank(r.approver_role))
  FROM public.approval_rules r
  WHERE r.company_id = p_company_id AND r.document_type = p_document_type AND r.is_active = true
    AND CASE r.condition_operator
          WHEN 'greater_than' THEN p_amount > COALESCE(r.condition_value, 0)
          WHEN 'greater_equal' THEN p_amount >= COALESCE(r.condition_value, 0)
          ELSE true
        END
$$;


ALTER FUNCTION public.approval_rule_strictest_rank(p_company_id uuid, p_document_type text, p_amount numeric) OWNER TO postgres;

--
-- Name: approval_rule_update(uuid, uuid, text, text, text, text, numeric, text, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.approval_rule_update(p_company_id uuid, p_rule_id uuid, p_actor text, p_name text, p_condition_field text, p_condition_operator text, p_condition_value numeric, p_approver_role text, p_is_active boolean) RETURNS SETOF public.approval_rules
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
DECLARE
  v_role pg_catalog.text;
  v_before public.approval_rules;
  v_after public.approval_rules;
  v_rule_role pg_catalog.text;
BEGIN
  PERFORM public.approval_rule_assert_caller(p_company_id, p_actor);
  v_role := public.approval_rule_actor_role(p_company_id, p_actor);
  PERFORM public.approval_rule_assert_input(p_name, p_approver_role, p_condition_operator, p_condition_field, p_condition_value);
  PERFORM public.approval_rule_assert_may_demand(v_role, p_approver_role);
  SELECT * INTO v_before FROM public.approval_rules r WHERE r.id = p_rule_id AND r.company_id = p_company_id FOR UPDATE;
  IF NOT FOUND THEN RETURN; END IF;
  v_rule_role := COALESCE(v_before.approver_role, 'admin');
  IF public.approval_actor_rank(v_role) < public.approval_required_rank(v_rule_role) THEN
    RAISE EXCEPTION 'This rule requires the % role; you do not hold it, so you cannot create, change or delete it', v_rule_role
      USING ERRCODE = 'RB001', DETAIL = v_rule_role;
  END IF;
  IF public.approval_rule_weakens(v_before, false, p_approver_role, p_is_active, p_condition_operator, p_condition_value)
     AND NOT public.approval_rule_may_weaken(v_role, v_rule_role) THEN
    RAISE EXCEPTION 'Only a role above % can lower, deactivate, delete or narrow this %-level rule', v_rule_role, v_rule_role
      USING ERRCODE = 'RB002', DETAIL = v_rule_role;
  END IF;
  UPDATE public.approval_rules r SET
    name = COALESCE(public.approval_rule_js_trim(p_name), r.name),
    condition_field = COALESCE(p_condition_field, r.condition_field),
    condition_operator = COALESCE(p_condition_operator, r.condition_operator),
    condition_value = COALESCE(p_condition_value, r.condition_value),
    approver_role = COALESCE(p_approver_role, r.approver_role),
    is_active = COALESCE(p_is_active, r.is_active),
    updated_at = pg_catalog.now()
  WHERE r.id = p_rule_id AND r.company_id = p_company_id
  RETURNING * INTO v_after;
  PERFORM public.approval_rule_audit(p_company_id, p_actor, v_role, 'update', p_rule_id, v_before, v_after);
  RETURN NEXT v_after;
END
$$;


ALTER FUNCTION public.approval_rule_update(p_company_id uuid, p_rule_id uuid, p_actor text, p_name text, p_condition_field text, p_condition_operator text, p_condition_value numeric, p_approver_role text, p_is_active boolean) OWNER TO postgres;

--
-- Name: approval_rule_weakens(public.approval_rules, boolean, text, boolean, text, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.approval_rule_weakens(p_before public.approval_rules, p_delete boolean, p_approver_role text, p_is_active boolean, p_operator text, p_value numeric) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
DECLARE
  v_rule_role pg_catalog.text := COALESCE(p_before.approver_role, 'admin');
  v_was_op pg_catalog.text := p_before.condition_operator;
  v_was_value pg_catalog.numeric := COALESCE(p_before.condition_value, 0);
  v_next_op pg_catalog.text := COALESCE(p_operator, p_before.condition_operator);
  v_next_value pg_catalog.numeric := COALESCE(p_value, p_before.condition_value, 0);
  -- lowerBound: greater_than → (value, exclusive), greater_equal → (value, inclusive), else (-∞, inclusive).
  v_was_bounded pg_catalog.bool := v_was_op IN ('greater_than', 'greater_equal');
  v_next_bounded pg_catalog.bool := v_next_op IN ('greater_than', 'greater_equal');
BEGIN
  IF p_delete THEN RETURN true; END IF;
  IF p_approver_role IS NOT NULL
     AND public.approval_required_rank(p_approver_role) < public.approval_required_rank(v_rule_role) THEN
    RETURN true;
  END IF;
  IF p_is_active IS FALSE THEN RETURN true; END IF;
  IF NOT COALESCE(v_next_bounded, false) THEN RETURN false; END IF;      -- next starts at -∞: covers everything
  IF NOT COALESCE(v_was_bounded, false) THEN RETURN true; END IF;        -- was -∞, now a finite bound
  RETURN v_next_value > v_was_value
      OR (v_next_value = v_was_value AND v_was_op = 'greater_equal' AND v_next_op = 'greater_than');
END
$$;


ALTER FUNCTION public.approval_rule_weakens(p_before public.approval_rules, p_delete boolean, p_approver_role text, p_is_active boolean, p_operator text, p_value numeric) OWNER TO postgres;

