    primary_color text DEFAULT '#0d9488'::text,
    idle_timeout_minutes integer DEFAULT 480 NOT NULL,
    is_demo boolean DEFAULT false NOT NULL,
    client_query_whatsapp text,
    cipc_annual_return_submitted boolean DEFAULT false NOT NULL,
    cipc_annual_return_submitted_at timestamp with time zone,
    require_project_on_cos boolean DEFAULT false NOT NULL,
    fx_documents_enabled boolean DEFAULT false NOT NULL,
    CONSTRAINT companies_chase_grace_days_check CHECK (((chase_grace_days >= 0) AND (chase_grace_days <= 30))),
    CONSTRAINT companies_entity_type_check CHECK ((entity_type = ANY (ARRAY['pty'::text, 'cc'::text, 'trust'::text]))),
    CONSTRAINT companies_functional_currency_zar CHECK (((functional_currency)::text = 'ZAR'::text)),
    CONSTRAINT companies_portal_mode_check CHECK (((portal_mode)::text = ANY (ARRAY[('full'::character varying)::text, ('invoices_only'::character varying)::text, ('statements_only'::character varying)::text])))
);

