--
-- Name: create_company_with_owner(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.create_company_with_owner(payload jsonb) RETURNS public.companies
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  caller_id        text := auth.uid();
  is_first_company boolean;
  new_row          public.companies;
BEGIN
  IF caller_id IS NULL OR caller_id = '' THEN
    RAISE EXCEPTION 'create_company_with_owner: not authenticated';
  END IF;

  IF COALESCE(payload->>'name', '') = '' THEN
    RAISE EXCEPTION 'create_company_with_owner: name is required';
  END IF;

  INSERT INTO public.companies (
    name, registered_name, trading_name, registration_number, vat_number, tax_number,
    email, phone, website,
    address_line1, address_line2, city, province, postal_code, country,
    logo_data,
    bank_name, bank_account_number, bank_branch_code, bank_account_type,
    financial_year_start, vat_period, vat_period_alignment, vat_system_type, default_currency
  ) VALUES (
    payload->>'name',
    payload->>'name',
    payload->>'tradingName',
    payload->>'registrationNumber',
    payload->>'vatNumber',
    payload->>'taxNumber',
    payload->>'email',
    payload->>'phone',
    payload->>'website',
    payload->>'addressLine1',
    payload->>'addressLine2',
    payload->>'city',
    payload->>'province',
    payload->>'postalCode',
    COALESCE(payload->>'country', 'South Africa'),
    payload->>'logoData',
    payload->>'bankName',
    payload->>'bankAccountNumber',
    payload->>'bankBranchCode',
    COALESCE(payload->>'bankAccountType', 'current'),
    COALESCE((payload->>'financialYearStart')::int, 3),
    COALESCE(payload->>'vatPeriod', 'bi-monthly'),
    COALESCE(payload->>'vatPeriodAlignment', 'odd'),
    -- A company created as "not registered for VAT" sends vatPeriod='none';
    -- keep vat_system_type in step so the two columns never disagree, because
    -- the AFS accounting-policy notes read vat_system_type.
    COALESCE(
      payload->>'vatSystemType',
      CASE WHEN LOWER(TRIM(COALESCE(payload->>'vatPeriod', ''))) = 'none'
           THEN 'none' ELSE 'invoice' END
    ),
    COALESCE(payload->>'defaultCurrency', 'ZAR')
  ) RETURNING * INTO new_row;

  SELECT NOT EXISTS (
    SELECT 1 FROM public.company_users WHERE user_id = caller_id
  ) INTO is_first_company;

  INSERT INTO public.company_users (company_id, user_id, role, is_default)
  VALUES (new_row.id, caller_id, 'owner', is_first_company);

  -- New: seed the default taxonomy so every workbench/portfolio/AFS feature
  -- has the GL accounts and fiscal periods it expects on day 1.
  PERFORM public.seed_company_default_taxonomy(new_row.id);

  RETURN new_row;
END;
$$;


ALTER FUNCTION public.create_company_with_owner(payload jsonb) OWNER TO postgres;

--
-- Name: credit_note_approval_gate(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.credit_note_approval_gate() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
DECLARE
  v_type pg_catalog.text;
  v_enabled_at pg_catalog.timestamptz;
  v_demanded pg_catalog.int4;
BEGIN
  IF COALESCE(NEW.status, '') IN ('draft', 'cancelled') THEN RETURN NULL; END IF;
  IF TG_OP = 'UPDATE' AND COALESCE(OLD.status, '') NOT IN ('draft', 'cancelled') THEN
    RETURN NULL;
  END IF;
  v_type := CASE NEW.type WHEN 'customer' THEN 'customer_credit_note'
                          WHEN 'supplier' THEN 'supplier_credit_note' END;
  SELECT ae.enabled_at INTO v_enabled_at
  FROM public.approval_enforcement ae
  WHERE ae.company_id = NEW.company_id AND ae.document_type = v_type;
  IF NOT FOUND THEN RETURN NULL; END IF;

  v_demanded := public.approval_rule_strictest_rank(
    NEW.company_id, v_type,
    public.approval_credit_note_gate_amount(NEW.total_amount, NEW.subtotal, NEW.tax_amount));
  IF v_demanded IS NULL THEN RETURN NULL; END IF;

  IF EXISTS (
    SELECT 1 FROM public.approval_requests ar
    LEFT JOIN public.approval_rules rl ON rl.id = ar.rule_id AND rl.company_id = ar.company_id
    WHERE ar.company_id = NEW.company_id AND ar.document_type = v_type
      AND ar.document_id = NEW.id AND ar.status = 'approved'
      AND ar.decided_at >= v_enabled_at
      AND ar.document_digest = public.approval_document_digest(NEW.company_id, v_type, NEW.id)
      AND COALESCE(ar.required_role, rl.approver_role) IS NOT NULL
      AND public.approval_required_rank(COALESCE(ar.required_role, rl.approver_role)) >= v_demanded
  ) THEN
    RETURN NULL;
  END IF;

  RAISE EXCEPTION 'R035_APPROVAL_REQUIRED: credit note % cannot be posted without an approval for its current content', NEW.id
    USING HINT = 'Raise an approval request and have it approved, then approve the credit note.';
END
$$;


ALTER FUNCTION public.credit_note_approval_gate() OWNER TO postgres;

