    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    AS $$ SELECT pg_catalog.round(p_amount OPERATOR(pg_catalog.*) p_rate, 2) $$;


ALTER FUNCTION public.fx_functional(p_amount numeric, p_rate numeric) OWNER TO postgres;

--
-- Name: fx_row_is_foreign(uuid, text[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fx_row_is_foreign(p_company_id uuid, p_codes text[]) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM pg_catalog.unnest(p_codes) AS code
    WHERE NULLIF(pg_catalog.upper(pg_catalog.btrim(code)), '') IS NOT NULL
      AND pg_catalog.upper(pg_catalog.btrim(code)) IS DISTINCT FROM
          (SELECT c.functional_currency FROM public.companies c WHERE c.id = p_company_id)
  )
$$;


ALTER FUNCTION public.fx_row_is_foreign(p_company_id uuid, p_codes text[]) OWNER TO postgres;

--
-- Name: fx_settlement_refusal(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fx_settlement_refusal() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
DECLARE
  v_codes pg_catalog.text[];
BEGIN
  IF TG_TABLE_NAME = 'supplier_invoices' THEN
    v_codes := ARRAY[NEW.currency_code, NEW.currency];
  ELSIF TG_TABLE_NAME = 'customer_invoices' THEN
    v_codes := ARRAY[NEW.currency_code, pg_catalog.to_jsonb(NEW) ->> 'currency'];
  ELSE
    v_codes := ARRAY[NEW.currency];
  END IF;
  IF NEW.company_id IS NOT NULL AND public.fx_row_is_foreign(NEW.company_id, v_codes) THEN
    RAISE EXCEPTION 'FX_SETTLEMENT_REFUSED: % % is in % — settling a foreign-currency document is not supported yet',
      TG_TABLE_NAME, NEW.id, pg_catalog.array_to_string(v_codes, '/')
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END $$;


ALTER FUNCTION public.fx_settlement_refusal() OWNER TO postgres;

--
-- Name: generate_adjustment_number(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.generate_adjustment_number() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  adj_year INT;
  next_seq INT;
  prev_lock_timeout TEXT;
BEGIN
  IF NEW.adjustment_number IS NOT NULL THEN
    RETURN NEW;
  END IF;
  adj_year := EXTRACT(YEAR FROM COALESCE(NEW.adjustment_date, CURRENT_DATE));
  -- Bound the wait at 5 s, never loosen a caller's tighter bound (0 = unbounded).
  prev_lock_timeout := current_setting('lock_timeout');
  IF prev_lock_timeout::interval = interval '0' OR prev_lock_timeout::interval > interval '5s' THEN
    PERFORM set_config('lock_timeout', '5s', true);
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(NEW.company_id::text || ':' || adj_year, 857));
  PERFORM set_config('lock_timeout', prev_lock_timeout, true);
  SELECT COALESCE(MAX(
    CAST(NULLIF(SPLIT_PART(adjustment_number, '-', 3), '') AS INT)
  ), 0) + 1 INTO next_seq
  FROM accounting_adjustments
  WHERE company_id = NEW.company_id
    AND adjustment_number LIKE 'ADJ-' || adj_year || '-%';
  NEW.adjustment_number := 'ADJ-' || adj_year || '-' || LPAD(next_seq::TEXT, GREATEST(5, LENGTH(next_seq::TEXT)), '0');
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.generate_adjustment_number() OWNER TO postgres;

