--
-- Name: manual_journal_approval_gate(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.manual_journal_approval_gate() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
DECLARE
  v_enabled_at pg_catalog.timestamptz;
  v_demanded pg_catalog.int4;
BEGIN
  IF TG_OP = 'UPDATE' AND OLD.approval_document_type IS NOT NULL
     AND NEW.approval_document_type IS DISTINCT FROM OLD.approval_document_type THEN
    RAISE EXCEPTION 'R035_APPROVAL_MARKER: journal % is a manual journal and stays one', NEW.id
      USING HINT = 'The approval marker on a journal cannot be removed or changed.';
  END IF;
  IF COALESCE(NEW.approval_document_type, '') <> 'manual_journal' OR COALESCE(NEW.status, '') <> 'posted' THEN
    RETURN NULL;
  END IF;
  IF TG_OP = 'UPDATE' AND OLD.status IS NOT DISTINCT FROM 'posted' THEN RETURN NULL; END IF;

  SELECT ae.enabled_at INTO v_enabled_at
  FROM public.approval_enforcement ae
  WHERE ae.company_id = NEW.company_id AND ae.document_type = 'manual_journal';
  IF NOT FOUND THEN RETURN NULL; END IF;

  -- No gated path INSERTs a journal posted: a manual journal is drafted, then
  -- posted. One inserted posted AND marked has no lines yet — the amount and
  -- the digest read them — and no approval can predate it, so under
  -- enforcement it is refused outright rather than judged on an empty journal
  -- its lines arrive in after the check.
  IF TG_OP = 'INSERT' THEN
    RAISE EXCEPTION 'R035_APPROVAL_REQUIRED: manual journal % cannot be inserted already posted', NEW.id
      USING HINT = 'Insert the journal as a draft, have it approved, then post it.';
  END IF;

  v_demanded := public.approval_rule_strictest_rank(
    NEW.company_id, 'manual_journal', public.approval_manual_journal_gate_amount(NEW.company_id, NEW.id));
  IF v_demanded IS NULL THEN RETURN NULL; END IF;

  IF EXISTS (
    SELECT 1 FROM public.approval_requests ar
    LEFT JOIN public.approval_rules rl ON rl.id = ar.rule_id AND rl.company_id = ar.company_id
    WHERE ar.company_id = NEW.company_id AND ar.document_type = 'manual_journal'
      AND ar.document_id = NEW.id AND ar.status = 'approved'
      AND ar.decided_at >= v_enabled_at
      AND ar.document_digest = public.approval_document_digest(NEW.company_id, 'manual_journal', NEW.id)
      AND COALESCE(ar.required_role, rl.approver_role) IS NOT NULL
      AND public.approval_required_rank(COALESCE(ar.required_role, rl.approver_role)) >= v_demanded
  ) THEN
    RETURN NULL;
  END IF;

  RAISE EXCEPTION 'R035_APPROVAL_REQUIRED: manual journal % cannot be posted without an approval for its current content', NEW.id
    USING HINT = 'Raise an approval request and have it approved, then post the journal.';
END
$$;


ALTER FUNCTION public.manual_journal_approval_gate() OWNER TO postgres;

--
-- Name: oauth_apps_guard_trust_flags(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.oauth_apps_guard_trust_flags() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF coalesce(current_setting('isaflow.allow_trust_flag_write', true), '') = 'on' THEN
    RETURN NEW;
  END IF;

  IF TG_OP = 'INSERT' THEN
    -- A fresh row may only arrive untrusted. Both columns DEFAULT FALSE, so a
    -- writer that does not name them is unaffected.
    IF NEW.is_verified OR NEW.is_first_party THEN
      RAISE EXCEPTION
        'oauth_apps: is_verified/is_first_party may not be set by the application'
        USING HINT = 'These decide whether an app may brand the consent screen. '
                     'To change one deliberately, SET LOCAL isaflow.allow_trust_flag_write = ''on'' '
                     'in the same transaction.';
    END IF;
  ELSIF NEW.is_verified IS DISTINCT FROM OLD.is_verified
     OR NEW.is_first_party IS DISTINCT FROM OLD.is_first_party THEN
    -- IS DISTINCT FROM, not <>: these are NOT NULL today, but a nullable
    -- future column would make <> return NULL and skip the guard.
    RAISE EXCEPTION
      'oauth_apps: is_verified/is_first_party may not be changed by the application'
      USING HINT = 'SET LOCAL isaflow.allow_trust_flag_write = ''on'' in the same transaction.';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION public.oauth_apps_guard_trust_flags() OWNER TO postgres;

--
-- Name: payment_approval_cleared(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.payment_approval_cleared(p_company_id uuid, p_document_type text, p_document_id uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
DECLARE
  v_enabled_at pg_catalog.timestamptz;
  v_demanded pg_catalog.int4;
BEGIN
  SELECT ae.enabled_at INTO v_enabled_at
  FROM public.approval_enforcement ae
  WHERE ae.company_id = p_company_id AND ae.document_type = p_document_type;
  IF NOT FOUND THEN RETURN true; END IF;

  IF p_document_type = 'payment_batch' THEN
    v_demanded := public.approval_payment_batch_strictest_rank(p_company_id, p_document_id);
  ELSE
    v_demanded := public.approval_rule_strictest_rank(p_company_id, 'supplier_payment',
      (SELECT public.approval_supplier_payment_gate_amount(sp.total_amount) FROM public.supplier_payments sp
       WHERE sp.id = p_document_id AND sp.company_id = p_company_id));
  END IF;
  IF v_demanded IS NULL THEN RETURN true; END IF;

  RETURN EXISTS (
    SELECT 1 FROM public.approval_requests ar
    LEFT JOIN public.approval_rules rl ON rl.id = ar.rule_id AND rl.company_id = ar.company_id
    WHERE ar.company_id = p_company_id AND ar.document_type = p_document_type
      AND ar.document_id = p_document_id AND ar.status = 'approved'
      AND ar.decided_at >= v_enabled_at
      AND ar.document_digest = public.approval_document_digest(p_company_id, p_document_type, p_document_id)
      AND COALESCE(ar.required_role, rl.approver_role) IS NOT NULL
      AND public.approval_required_rank(COALESCE(ar.required_role, rl.approver_role)) >= v_demanded);
END
$$;


ALTER FUNCTION public.payment_approval_cleared(p_company_id uuid, p_document_type text, p_document_id uuid) OWNER TO postgres;

--
-- Name: payment_batch_approval_gate(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.payment_batch_approval_gate() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
BEGIN
  IF COALESCE(NEW.status, '') NOT IN ('approved', 'processed') THEN RETURN NULL; END IF;
  IF TG_OP = 'UPDATE' AND OLD.status IS NOT DISTINCT FROM NEW.status THEN RETURN NULL; END IF;
  IF public.payment_approval_cleared(NEW.company_id, 'payment_batch', NEW.id) THEN RETURN NULL; END IF;
  RAISE EXCEPTION 'R035_APPROVAL_REQUIRED: payment batch % cannot be approved or paid without an approval for its current content', NEW.id
    USING HINT = 'Raise an approval request for the batch and have it approved, then approve or process the batch.';
END
$$;


ALTER FUNCTION public.payment_batch_approval_gate() OWNER TO postgres;

--
-- Name: payment_batch_member_gate(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.payment_batch_member_gate() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
DECLARE
  r record;
BEGIN
  IF TG_OP = 'INSERT' THEN
    FOR r IN
      SELECT n.company_id, n.batch_id, (pg_catalog.array_agg(n.id ORDER BY n.id))[1] AS member
      FROM new_rows n
      WHERE n.batch_id IS NOT NULL AND COALESCE(n.status, '') IN ('approved', 'processed', 'reconciled')
      GROUP BY n.company_id, n.batch_id
    LOOP
      IF NOT public.payment_approval_cleared(r.company_id, 'payment_batch', r.batch_id) THEN
        RAISE EXCEPTION 'R035_APPROVAL_REQUIRED: batch member % cannot be approved or paid without an approval of batch % for its current content', r.member, r.batch_id
          USING HINT = 'Raise an approval request for the batch and have it approved, then approve or process the batch.';
      END IF;
    END LOOP;
  ELSE
    FOR r IN
      SELECT n.company_id, n.batch_id, (pg_catalog.array_agg(n.id ORDER BY n.id))[1] AS member
      FROM new_rows n JOIN old_rows o ON o.id = n.id
      WHERE n.batch_id IS NOT NULL AND COALESCE(n.status, '') IN ('approved', 'processed', 'reconciled')
        AND o.status IS DISTINCT FROM n.status
        AND NOT (o.status IN ('processed', 'reconciled') AND n.status IN ('processed', 'reconciled'))
      GROUP BY n.company_id, n.batch_id
    LOOP
      IF NOT public.payment_approval_cleared(r.company_id, 'payment_batch', r.batch_id) THEN
        RAISE EXCEPTION 'R035_APPROVAL_REQUIRED: batch member % cannot be approved or paid without an approval of batch % for its current content', r.member, r.batch_id
          USING HINT = 'Raise an approval request for the batch and have it approved, then approve or process the batch.';
      END IF;
    END LOOP;
  END IF;
  RETURN NULL;
END
$$;


ALTER FUNCTION public.payment_batch_member_gate() OWNER TO postgres;

--
-- Name: practice_pcro_mirror_columns(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.practice_pcro_mirror_columns() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'UPDATE' THEN
    -- Carry whichever side the statement actually changed over to the other.
    IF NEW.rate_per_hour IS DISTINCT FROM OLD.rate_per_hour THEN
      NEW.rate := NEW.rate_per_hour;
    ELSIF NEW.rate IS DISTINCT FROM OLD.rate THEN
      NEW.rate_per_hour := NEW.rate;
    END IF;
    IF NEW.staff_user_id IS DISTINCT FROM OLD.staff_user_id THEN
      NEW.user_id := NEW.staff_user_id;
    ELSIF NEW.user_id IS DISTINCT FROM OLD.user_id THEN
      NEW.staff_user_id := NEW.user_id;
    END IF;
    NEW.staff_user_id := COALESCE(NEW.staff_user_id, NEW.user_id);
    NEW.user_id       := COALESCE(NEW.user_id, NEW.staff_user_id);
    NEW.rate_per_hour := COALESCE(NEW.rate_per_hour, NEW.rate);
    NEW.rate          := COALESCE(NEW.rate, NEW.rate_per_hour);
  ELSE
    -- INSERT: there is no OLD row to say which side the writer meant, so the newer
    -- column is authoritative. This fills a legacy half left NULL and also reconciles
    -- two halves supplied together that disagree, which would otherwise pass through.
    NEW.staff_user_id := COALESCE(NEW.staff_user_id, NEW.user_id);
    NEW.rate_per_hour := COALESCE(NEW.rate_per_hour, NEW.rate);
    NEW.user_id       := NEW.staff_user_id;
    NEW.rate          := NEW.rate_per_hour;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.practice_pcro_mirror_columns() OWNER TO postgres;

--
-- Name: refresh_gl_account_balances_on_status_change(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.refresh_gl_account_balances_on_status_change() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  acct UUID;
  per  UUID;
BEGIN
  -- Recompute each account this entry touches from posted lines only, so the
  -- cache equals the reporting truth regardless of which way the status moved
  -- (draft->posted adds the entry's lines, posted->reversed/draft removes them).
  -- This fires once per status change (not once per line), so a full recompute
  -- per affected account stays O(lines-in-account-for-period) and avoids the
  -- O(N^2) blow-up that pushed mig 465's line trigger to incremental deltas.
  --
  -- Recompute under BOTH the new and old fiscal period: if a single UPDATE ever
  -- changes status AND fiscal_period_id together, the entry's contribution is
  -- removed from the old period and rebuilt under the new one (no stale row).
  -- Entries with no fiscal period cannot be cached (keyed on fiscal_period_id),
  -- so NULL periods are skipped.
  --
  -- NOTE: the aggregate SELECT has no GROUP BY, so when no posted lines remain
  -- for (acct, per) it still returns one row of zeros — the ON CONFLICT upsert
  -- then sets the cached balance to 0 rather than leaving a stale value.
  FOR per IN
    SELECT DISTINCT p
    FROM unnest(ARRAY[NEW.fiscal_period_id, OLD.fiscal_period_id]) AS u(p)
    WHERE p IS NOT NULL
  LOOP
    FOR acct IN
      SELECT DISTINCT gl_account_id FROM gl_journal_lines WHERE journal_entry_id = NEW.id
    LOOP
      INSERT INTO gl_account_balances (gl_account_id, fiscal_period_id, debit_total, credit_total, balance)
      SELECT
        acct, per,
        COALESCE(SUM(jl.debit), 0),
        COALESCE(SUM(jl.credit), 0),
        COALESCE(SUM(jl.debit), 0) - COALESCE(SUM(jl.credit), 0)
      FROM gl_journal_lines jl
      JOIN gl_journal_entries je ON je.id = jl.journal_entry_id
      WHERE jl.gl_account_id = acct
        AND je.fiscal_period_id = per
        AND je.status = 'posted'
      ON CONFLICT (gl_account_id, fiscal_period_id) DO UPDATE SET
        debit_total = EXCLUDED.debit_total,
        credit_total = EXCLUDED.credit_total,
        balance = EXCLUDED.balance,
        updated_at = NOW();
    END LOOP;
  END LOOP;

  RETURN NEW;
END;
$$;


ALTER FUNCTION public.refresh_gl_account_balances_on_status_change() OWNER TO postgres;

--
-- Name: resolve_je_fiscal_period(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.resolve_je_fiscal_period() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.fiscal_period_id IS NULL THEN
    SELECT fp.id INTO NEW.fiscal_period_id
    FROM fiscal_periods fp
    WHERE fp.company_id = NEW.company_id
      AND NEW.entry_date BETWEEN fp.start_date AND fp.end_date
    ORDER BY fp.start_date
    LIMIT 1;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.resolve_je_fiscal_period() OWNER TO postgres;

