--
-- Name: seed_company_fiscal_periods(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.seed_company_fiscal_periods(p_company_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  cur_year integer := EXTRACT(year FROM CURRENT_DATE)::integer;
  yr integer;
  m  integer;
BEGIN
  -- Use uq_fiscal_periods_company_year_period (mig 220) for ON CONFLICT.
  FOR yr IN cur_year..(cur_year + 1) LOOP
    FOR m IN 1..12 LOOP
      INSERT INTO fiscal_periods (
        company_id, period_name, period_number, fiscal_year, start_date, end_date, status
      ) VALUES (
        p_company_id,
        TO_CHAR(MAKE_DATE(yr, m, 1), 'FMMonth YYYY'),
        m,
        yr,
        MAKE_DATE(yr, m, 1),
        (MAKE_DATE(yr, m, 1) + INTERVAL '1 month' - INTERVAL '1 day')::date,
        'open'
      ) ON CONFLICT (company_id, fiscal_year, period_number) DO NOTHING;
    END LOOP;
  END LOOP;
END;
$$;


