--
-- Name: set_asset_book_value(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.set_asset_book_value() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.current_book_value IS NULL THEN
    NEW.current_book_value := NEW.purchase_price;
  END IF;
  IF NEW.tax_book_value IS NULL THEN
    NEW.tax_book_value := NEW.purchase_price;
  END IF;
  RETURN NEW;
END;
$$;


