--
-- Name: supplier_bank_details_present(text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.supplier_bank_details_present(p_bank_name text, p_account_number text, p_branch_code text, p_account_type text, p_account_holder text) RETURNS boolean
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
  SELECT public.supplier_bank_fingerprint(p_bank_name, p_account_number, p_branch_code, p_account_type, p_account_holder)
         IS DISTINCT FROM public.supplier_bank_fingerprint(NULL, NULL, NULL, NULL, NULL)
$$;


ALTER FUNCTION public.supplier_bank_details_present(p_bank_name text, p_account_number text, p_branch_code text, p_account_type text, p_account_holder text) OWNER TO postgres;

--
-- Name: supplier_bank_fingerprint(text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.supplier_bank_fingerprint(p_bank_name text, p_account_number text, p_branch_code text, p_account_type text, p_account_holder text) RETURNS text
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
  SELECT pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(pg_catalog.jsonb_build_array(
    NULLIF(pg_catalog.lower(pg_catalog.regexp_replace(pg_catalog.btrim(p_bank_name), '\s+', ' ', 'g')), ''),
    NULLIF(pg_catalog.regexp_replace(p_account_number, '[^0-9]', '', 'g'), ''),
    NULLIF(pg_catalog.regexp_replace(p_branch_code, '[^0-9]', '', 'g'), ''),
    NULLIF(pg_catalog.lower(pg_catalog.regexp_replace(pg_catalog.btrim(p_account_type), '\s+', ' ', 'g')), ''),
    NULLIF(pg_catalog.lower(pg_catalog.regexp_replace(pg_catalog.btrim(p_account_holder), '\s+', ' ', 'g')), '')
  )::pg_catalog.text, 'UTF8')), 'hex')
$$;


ALTER FUNCTION public.supplier_bank_fingerprint(p_bank_name text, p_account_number text, p_branch_code text, p_account_type text, p_account_holder text) OWNER TO postgres;

--
-- Name: supplier_bank_verification_append_only(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.supplier_bank_verification_append_only() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
BEGIN
  -- Nested, not AND: a TRUNCATE has no OLD row to read.
  IF TG_OP = 'DELETE' THEN
    IF NOT EXISTS (SELECT 1 FROM public.suppliers x WHERE x.id = OLD.supplier_id AND x.company_id = OLD.company_id) THEN
      RETURN OLD;
    END IF;
  END IF;
  RAISE EXCEPTION 'supplier_bank_verifications is append-only (% refused)', TG_OP USING ERRCODE = '42501';
END
$$;


ALTER FUNCTION public.supplier_bank_verification_append_only() OWNER TO postgres;

--
-- Name: supplier_bank_verification_guard(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.supplier_bank_verification_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
DECLARE
  s RECORD;
  roster pg_catalog.jsonb;
BEGIN
  NEW.verified_at := pg_catalog.now();
  NEW.seq := pg_catalog.nextval(pg_catalog.pg_get_serial_sequence('public.supplier_bank_verifications', 'seq'));
  -- Whoever verifies (or switches on) holds at least the verifier floor,
  -- admin. The rank ladder lives in TypeScript (APPROVER_RANK); these are
  -- its roles ranking at or above admin, pinned against it by
  -- supplierBankVerificationCensus. A rule can raise the bar above the floor
  -- only in TypeScript, which judges it.
  IF NOT EXISTS (
    SELECT 1 FROM public.company_users cu JOIN public.users u ON u.id = cu.user_id
    WHERE cu.company_id = NEW.company_id AND cu.user_id = NEW.verified_by
      AND cu.role IN ('super_admin', 'owner', 'system', 'admin')
      AND u.is_active IS TRUE AND u.suspended_at IS NULL AND COALESCE(pg_catalog.lower(u.status), 'active') = 'active'
  ) THEN
    RAISE EXCEPTION 'supplier_bank_verifications: % does not hold the admin role or above, in good standing, in this company', NEW.verified_by
      USING ERRCODE = '23514';
  END IF;
  SELECT public.supplier_bank_fingerprint(x.bank_name, x.bank_account_number, x.bank_branch_code,
                                          x.bank_account_type, x.bank_account_holder) AS fingerprint,
         COALESCE(x.bank_details_setters::pg_catalog.text[], '{}') AS setters
    INTO s
    FROM public.suppliers x
   WHERE x.id = NEW.supplier_id AND x.company_id = NEW.company_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'supplier_bank_verifications: supplier % not found in company %', NEW.supplier_id, NEW.company_id
      USING ERRCODE = '23503';
  END IF;
  IF NEW.fingerprint IS DISTINCT FROM s.fingerprint THEN
    RAISE EXCEPTION 'supplier_bank_verifications: the fingerprint is not the supplier''s current bank details'
      USING ERRCODE = '23514';
  END IF;
  IF NEW.kind = 'baseline' THEN
    -- Only the switch-on writes a baseline: the enforcement row its own
    -- transaction inserted, by the same person.
    IF NOT EXISTS (
      SELECT 1 FROM public.approval_enforcement ae
      WHERE ae.company_id = NEW.company_id AND ae.document_type = 'supplier_bank_details'
        AND ae.enabled_by = NEW.verified_by AND ae.enabled_at = pg_catalog.now()
    ) THEN
      RAISE EXCEPTION 'supplier_bank_verifications: a baseline is written only by switching the control on'
        USING ERRCODE = '23514';
    END IF;
    -- Only the company's FIRST switch-on baselines: once it has any row from
    -- an earlier transaction, switching off and on again accepts nothing —
    -- not a pending change, nor a supplier created or given details since.
    IF EXISTS (
      SELECT 1 FROM public.supplier_bank_verifications v
      WHERE v.company_id = NEW.company_id AND NOT (v.kind = 'baseline' AND v.verified_at = pg_catalog.now())
    ) THEN
      RAISE EXCEPTION 'supplier_bank_verifications: verification was switched on before in this company; no new baseline'
        USING ERRCODE = '23514';
    END IF;
    -- …and never twice for one supplier.
    IF EXISTS (
      SELECT 1 FROM public.supplier_bank_verifications v
      WHERE v.company_id = NEW.company_id AND v.supplier_id = NEW.supplier_id
    ) THEN
      RAISE EXCEPTION 'supplier_bank_verifications: supplier % already has verification history; it is not baselined again',
        NEW.supplier_id USING ERRCODE = '23514';
    END IF;
    -- Not details the switcher set: switching off, changing and switching on
    -- again must not verify the switcher's own change.
    IF NEW.verified_by = ANY (s.setters) THEN
      RAISE EXCEPTION 'supplier_bank_verifications: % set these bank details and cannot baseline them', NEW.verified_by
        USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.approval_enforcement ae
    WHERE ae.company_id = NEW.company_id AND ae.document_type = 'supplier_bank_details'
  ) THEN
    RAISE EXCEPTION 'supplier_bank_verifications: supplier bank verification is not enforced for this company'
      USING ERRCODE = '23514';
  END IF;
  -- A setter of the current details verifies only as the sole approver,
  -- recorded as such (the roster CHECK demands its snapshot).
  IF NEW.kind = 'verified' AND NEW.verified_by = ANY (s.setters) THEN
    RAISE EXCEPTION 'supplier_bank_verifications: % set these bank details and cannot verify them', NEW.verified_by
      USING ERRCODE = '23514';
  END IF;
  IF NEW.kind = 'self_verified' THEN
    IF NOT (NEW.verified_by = ANY (s.setters)) THEN
      RAISE EXCEPTION 'supplier_bank_verifications: self_verified is only for a setter of the details'
        USING ERRCODE = '23514';
    END IF;
    -- The roster recorded is the roster now (708's snapshot, which answers only
    -- for the request's own user and company), and in it no OTHER active
    -- member reaches the admin floor: the sole-approver exception, R-035 Q2.
    roster := public.approval_roster_snapshot(NEW.company_id, NEW.verified_by);
    IF NEW.roster_snapshot IS DISTINCT FROM roster THEN
      RAISE EXCEPTION 'supplier_bank_verifications: roster_snapshot is not the company roster now'
        USING ERRCODE = '23514';
    END IF;
    IF EXISTS (
      SELECT 1 FROM pg_catalog.jsonb_array_elements(roster -> 'others') e
      WHERE e ->> 'role' IN ('super_admin', 'owner', 'system', 'admin')
        AND (e ->> 'is_active') = 'true'
        AND COALESCE(e ->> 'suspended', 'false') = 'false'
        AND COALESCE(pg_catalog.lower(e ->> 'status'), 'active') = 'active'
    ) THEN
      RAISE EXCEPTION 'supplier_bank_verifications: another active member could verify, so self_verified is refused'
        USING ERRCODE = '23514';
    END IF;
  END IF;
  RETURN NEW;
END
$$;


ALTER FUNCTION public.supplier_bank_verification_guard() OWNER TO postgres;

--
-- Name: supplier_bank_verified(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.supplier_bank_verified(p_company_id uuid, p_supplier_id uuid) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
  SELECT COALESCE((
    SELECT v.fingerprint = public.supplier_bank_fingerprint(s.bank_name, s.bank_account_number, s.bank_branch_code,
                                                            s.bank_account_type, s.bank_account_holder)
    FROM public.suppliers s
    JOIN LATERAL (
      SELECT x.fingerprint FROM public.supplier_bank_verifications x
      WHERE x.company_id = s.company_id AND x.supplier_id = s.id
      ORDER BY x.seq DESC LIMIT 1
    ) v ON true
    WHERE s.company_id = p_company_id AND s.id = p_supplier_id
  ), false)
$$;


ALTER FUNCTION public.supplier_bank_verified(p_company_id uuid, p_supplier_id uuid) OWNER TO postgres;

