--
-- Name: supplier_invoice_approval_gate(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.supplier_invoice_approval_gate() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
DECLARE
  v_enabled_at pg_catalog.timestamptz;
BEGIN
  IF COALESCE(NEW.status, '') IN ('draft', 'pending_approval', 'cancelled') THEN RETURN NULL; END IF;
  IF TG_OP = 'UPDATE' AND COALESCE(OLD.status, '') NOT IN ('draft', 'pending_approval', 'cancelled') THEN
    RETURN NULL;
  END IF;
  IF COALESCE(pg_catalog.current_setting('isaflow.approval_gate_exempt', true), '') = 'import' THEN
    RETURN NULL;
  END IF;

  SELECT ae.enabled_at INTO v_enabled_at
  FROM public.approval_enforcement ae
  WHERE ae.company_id = NEW.company_id AND ae.document_type = 'supplier_invoice';
  IF NOT FOUND THEN RETURN NULL; END IF;

  IF NOT public.approval_supplier_invoice_rule_matches(
    NEW.company_id, public.approval_supplier_invoice_gate_amount(NEW.total_amount, NEW.functional_total)) THEN
    RETURN NULL;
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.approval_requests ar
    WHERE ar.company_id = NEW.company_id AND ar.document_type = 'supplier_invoice'
      AND ar.document_id = NEW.id AND ar.status = 'approved'
      AND ar.decided_at >= v_enabled_at
      AND ar.document_digest = public.approval_document_digest(NEW.company_id, 'supplier_invoice', NEW.id)
  ) THEN
    RETURN NULL;
  END IF;

  RAISE EXCEPTION 'R035_APPROVAL_REQUIRED: supplier invoice % cannot enter the AP population without an approval for its current content', NEW.id
    USING HINT = 'Raise an approval request and have it approved, then approve the invoice.';
END
$$;


ALTER FUNCTION public.supplier_invoice_approval_gate() OWNER TO postgres;

--
-- Name: supplier_payment_approval_gate(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.supplier_payment_approval_gate() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
BEGIN
  IF NEW.batch_id IS NOT NULL THEN RETURN NULL; END IF;
  IF COALESCE(NEW.status, '') NOT IN ('approved', 'processed', 'reconciled') THEN RETURN NULL; END IF;
  IF TG_OP = 'UPDATE' AND (OLD.status IS NOT DISTINCT FROM NEW.status
      OR (OLD.status IN ('processed', 'reconciled') AND NEW.status IN ('processed', 'reconciled'))) THEN
    RETURN NULL;
  END IF;
  IF TG_OP = 'INSERT' AND NEW.payment_method = 'refund' AND NEW.total_amount < 0 THEN RETURN NULL; END IF;
  IF TG_OP = 'INSERT'
     AND COALESCE(pg_catalog.current_setting('isaflow.approval_gate_exempt', true), '') = 'bank_feed' THEN
    RETURN NULL;
  END IF;

  IF public.payment_approval_cleared(NEW.company_id, 'supplier_payment', NEW.id) THEN RETURN NULL; END IF;
  RAISE EXCEPTION 'R035_APPROVAL_REQUIRED: supplier payment % cannot be approved or paid without an approval for its current content', NEW.id
    USING HINT = 'Raise an approval request and have it approved, then approve or process the payment.';
END
$$;


ALTER FUNCTION public.supplier_payment_approval_gate() OWNER TO postgres;

--
-- Name: supplier_payments_settles_provisional_same_company(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.supplier_payments_settles_provisional_same_company() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NEW.settles_provisional_je_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM gl_journal_entries
    WHERE id = NEW.settles_provisional_je_id AND company_id = NEW.company_id
  ) THEN
    RAISE EXCEPTION 'supplier payment % names provisional journal % of another company',
      NEW.id, NEW.settles_provisional_je_id
      USING ERRCODE = 'foreign_key_violation';
  END IF;
  RETURN NEW;
END $$;


ALTER FUNCTION public.supplier_payments_settles_provisional_same_company() OWNER TO postgres;

--
-- Name: take_number_lock(text, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.take_number_lock(p_scope text, p_seed bigint) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
  prev_lock_timeout TEXT;
BEGIN
  -- Bound the wait at 5 s, never loosen a caller's tighter bound (0 = unbounded).
  prev_lock_timeout := current_setting('lock_timeout');
  IF prev_lock_timeout::interval = interval '0' OR prev_lock_timeout::interval > interval '5s' THEN
    PERFORM set_config('lock_timeout', '5s', true);
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(p_scope, p_seed));
  PERFORM set_config('lock_timeout', prev_lock_timeout, true);
END;
$$;


ALTER FUNCTION public.take_number_lock(p_scope text, p_seed bigint) OWNER TO postgres;

--
-- Name: update_account_balances(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.update_account_balances() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  entry_status VARCHAR(20);
  period_id UUID;
  acct_id UUID;
  d_delta NUMERIC(15,2) := 0;
  c_delta NUMERIC(15,2) := 0;
BEGIN
  -- Get the entry status and period
  SELECT status, fiscal_period_id INTO entry_status, period_id
  FROM gl_journal_entries
  WHERE id = COALESCE(NEW.journal_entry_id, OLD.journal_entry_id);

  IF entry_status != 'posted' OR period_id IS NULL THEN
    RETURN COALESCE(NEW, OLD);
  END IF;

  acct_id := COALESCE(NEW.gl_account_id, OLD.gl_account_id);

  -- Compute delta: NEW adds, OLD subtracts.
  IF TG_OP = 'INSERT' THEN
    d_delta := COALESCE(NEW.debit, 0);
    c_delta := COALESCE(NEW.credit, 0);
  ELSIF TG_OP = 'DELETE' THEN
    d_delta := -COALESCE(OLD.debit, 0);
    c_delta := -COALESCE(OLD.credit, 0);
  ELSIF TG_OP = 'UPDATE' THEN
    -- Only fire delta if amounts or account changed
    IF NEW.gl_account_id != OLD.gl_account_id THEN
      -- Account changed: subtract from old, add to new (handled below by recursion is risky;
      -- safer to fall back to full recompute for the rare cross-account move)
      INSERT INTO gl_account_balances (gl_account_id, fiscal_period_id, debit_total, credit_total, balance)
      SELECT
        OLD.gl_account_id, period_id,
        COALESCE(SUM(jl.debit), 0),
        COALESCE(SUM(jl.credit), 0),
        COALESCE(SUM(jl.debit), 0) - COALESCE(SUM(jl.credit), 0)
      FROM gl_journal_lines jl
      JOIN gl_journal_entries je ON je.id = jl.journal_entry_id
      WHERE jl.gl_account_id = OLD.gl_account_id
        AND je.fiscal_period_id = period_id
        AND je.status = 'posted'
      ON CONFLICT (gl_account_id, fiscal_period_id) DO UPDATE SET
        debit_total = EXCLUDED.debit_total,
        credit_total = EXCLUDED.credit_total,
        balance = EXCLUDED.balance,
        updated_at = NOW();
      d_delta := COALESCE(NEW.debit, 0);
      c_delta := COALESCE(NEW.credit, 0);
    ELSE
      d_delta := COALESCE(NEW.debit, 0) - COALESCE(OLD.debit, 0);
      c_delta := COALESCE(NEW.credit, 0) - COALESCE(OLD.credit, 0);
    END IF;
  END IF;

  -- Try incremental upsert. If the cached row is missing, do a one-time full
  -- recompute so the cache bootstraps correctly.
  IF NOT EXISTS (
    SELECT 1 FROM gl_account_balances
    WHERE gl_account_id = acct_id AND fiscal_period_id = period_id
  ) THEN
    INSERT INTO gl_account_balances (gl_account_id, fiscal_period_id, debit_total, credit_total, balance)
    SELECT
      acct_id, period_id,
      COALESCE(SUM(jl.debit), 0),
      COALESCE(SUM(jl.credit), 0),
      COALESCE(SUM(jl.debit), 0) - COALESCE(SUM(jl.credit), 0)
    FROM gl_journal_lines jl
    JOIN gl_journal_entries je ON je.id = jl.journal_entry_id
    WHERE jl.gl_account_id = acct_id
      AND je.fiscal_period_id = period_id
      AND je.status = 'posted'
    ON CONFLICT (gl_account_id, fiscal_period_id) DO UPDATE SET
      debit_total = EXCLUDED.debit_total,
      credit_total = EXCLUDED.credit_total,
      balance = EXCLUDED.balance,
      updated_at = NOW();
  ELSE
    -- Incremental delta update — O(1)
    UPDATE gl_account_balances
    SET debit_total = debit_total + d_delta,
        credit_total = credit_total + c_delta,
        balance = (debit_total + d_delta) - (credit_total + c_delta),
        updated_at = NOW()
    WHERE gl_account_id = acct_id AND fiscal_period_id = period_id;
  END IF;

  RETURN COALESCE(NEW, OLD);
END;
$$;


ALTER FUNCTION public.update_account_balances() OWNER TO postgres;

