--
-- Name: ap_payment_document_backfill_candidates; Type: VIEW; Schema: public; Owner: migration_admin
--

CREATE VIEW public.ap_payment_document_backfill_candidates AS
 WITH base AS (
         SELECT b.id AS bank_transaction_id,
            b.company_id,
            b.transaction_date,
            b.bank_account_id,
            b.allocated_entity_name,
            b.allocation_type,
            round(abs(b.amount), 2) AS amount,
                CASE
                    WHEN (b.amount < (0)::numeric) THEN 'payment'::text
                    ELSE 'refund'::text
                END AS direction,
            jl.journal_entry_id
           FROM (public.bank_transactions b
             LEFT JOIN public.gl_journal_lines jl ON (((jl.id = b.matched_journal_line_id) AND (jl.company_id = b.company_id))))
          WHERE (((b.status)::text = 'allocated'::text) AND (b.amount <> (0)::numeric) AND ((b.allocation_type = 'supplier'::text) OR ((b.allocation_type = 'account'::text) AND (b.amount > (0)::numeric) AND (EXISTS ( SELECT 1
                   FROM (public.gl_journal_lines l
                     JOIN public.gl_accounts a ON (((a.id = l.gl_account_id) AND (a.company_id = l.company_id) AND ((a.account_subtype)::text = 'payable'::text))))
                  WHERE ((l.journal_entry_id = jl.journal_entry_id) AND (l.company_id = b.company_id) AND (l.credit > (0)::numeric)))))))
        ), resolved AS (
         SELECT base.bank_transaction_id,
            base.company_id,
            base.transaction_date,
            base.bank_account_id,
            base.allocated_entity_name,
            base.allocation_type,
            base.amount,
            base.direction,
            base.journal_entry_id,
            ( SELECT array_agg(s.id) AS array_agg
                   FROM public.suppliers s
                  WHERE ((s.company_id = base.company_id) AND ((s.name)::text = base.allocated_entity_name) AND (s.deleted_at IS NULL))) AS supplier_ids
           FROM base
        ), facts AS (
         SELECT resolved.bank_transaction_id,
            resolved.company_id,
            resolved.transaction_date,
            resolved.bank_account_id,
            resolved.allocated_entity_name,
            resolved.allocation_type,
            resolved.amount,
            resolved.direction,
            resolved.journal_entry_id,
            resolved.supplier_ids,
                CASE
                    WHEN (COALESCE(array_length(resolved.supplier_ids, 1), 0) = 1) THEN ((EXISTS ( SELECT 1
                       FROM public.supplier_invoices si
                      WHERE ((si.company_id = resolved.company_id) AND (si.supplier_id = resolved.supplier_ids[1])))) OR (EXISTS ( SELECT 1
                       FROM public.supplier_payments sp2
                      WHERE ((sp2.company_id = resolved.company_id) AND (sp2.supplier_id = resolved.supplier_ids[1])))))
                    ELSE false
                END AS supplier_has_history,
                CASE
                    WHEN ((resolved.direction = 'refund'::text) AND (COALESCE(array_length(resolved.supplier_ids, 1), 0) = 1)) THEN public.ap_supplier_on_account_credit(resolved.company_id, resolved.supplier_ids[1], resolved.transaction_date)
                    ELSE NULL::numeric
                END AS on_account_credit,
            je.status AS journal_status,
            public.ap_journal_entry_is_reversed(resolved.company_id, resolved.journal_entry_id) AS journal_reversed,
            je.description AS journal_description,
            je.created_by AS journal_created_by,
            ( SELECT COALESCE(sum((l.debit - l.credit)), (0)::numeric) AS "coalesce"
                   FROM public.gl_journal_lines l
                  WHERE ((l.journal_entry_id = resolved.journal_entry_id) AND (l.company_id = resolved.company_id))) AS journal_imbalance,
            ( SELECT COALESCE(sum((l.debit - l.credit)), (0)::numeric) AS "coalesce"
                   FROM (public.gl_journal_lines l
                     JOIN public.gl_accounts a ON (((a.id = l.gl_account_id) AND (a.company_id = resolved.company_id) AND ((a.account_subtype)::text = 'payable'::text))))
                  WHERE ((l.journal_entry_id = resolved.journal_entry_id) AND (l.company_id = resolved.company_id))) AS ap_movement,
            ( SELECT COALESCE(sum((l.credit - l.debit)), (0)::numeric) AS "coalesce"
                   FROM public.gl_journal_lines l
                  WHERE ((l.journal_entry_id = resolved.journal_entry_id) AND (l.company_id = resolved.company_id) AND (l.gl_account_id = resolved.bank_account_id))) AS bank_movement,
            (EXISTS ( SELECT 1
                   FROM public.supplier_payments sp
                  WHERE ((sp.company_id = resolved.company_id) AND ((sp.status)::text <> 'cancelled'::text) AND ((sp.gl_journal_entry_id = resolved.journal_entry_id) OR (((sp.reference)::text = (resolved.bank_transaction_id)::text) AND ((sp.gl_journal_entry_id IS NULL) OR (sp.gl_journal_entry_id = resolved.journal_entry_id))))))) AS has_document,
            (EXISTS ( SELECT 1
                   FROM public.supplier_payments sp
                  WHERE ((sp.company_id = resolved.company_id) AND ((sp.status)::text <> 'cancelled'::text) AND ((sp.reference)::text = (resolved.bank_transaction_id)::text) AND (sp.gl_journal_entry_id IS NOT NULL) AND (sp.gl_journal_entry_id IS DISTINCT FROM resolved.journal_entry_id)))) AS has_document_on_other_journal,
            (EXISTS ( SELECT 1
                   FROM public.supplier_payments sp
                  WHERE ((sp.company_id = resolved.company_id) AND ((sp.status)::text = 'cancelled'::text) AND ((sp.gl_journal_entry_id = resolved.journal_entry_id) OR (((sp.reference)::text = (resolved.bank_transaction_id)::text) AND (sp.gl_journal_entry_id IS NOT NULL) AND (NOT public.ap_journal_entry_is_reversed(resolved.company_id, sp.gl_journal_entry_id))))))) AS has_cancelled_document,
            ( SELECT count(*) AS count
                   FROM (public.bank_transactions b2
                     JOIN public.gl_journal_lines jl2 ON (((jl2.id = b2.matched_journal_line_id) AND (jl2.company_id = b2.company_id))))
                  WHERE ((b2.company_id = resolved.company_id) AND (jl2.journal_entry_id = resolved.journal_entry_id))) AS lines_on_this_journal
           FROM (resolved
             LEFT JOIN public.gl_journal_entries je ON (((je.id = resolved.journal_entry_id) AND (je.company_id = resolved.company_id))))
        )
 SELECT bank_transaction_id,
    company_id,
    transaction_date,
    bank_account_id,
    amount,
    journal_entry_id,
    journal_created_by,
    COALESCE(journal_description, (
        CASE
            WHEN (direction = 'refund'::text) THEN 'Refund from '::text
            ELSE 'Payment to '::text
        END || COALESCE(allocated_entity_name, 'supplier'::text))) AS description,
    allocated_entity_name,
        CASE
            WHEN (COALESCE(array_length(supplier_ids, 1), 0) = 1) THEN supplier_ids[1]
            ELSE NULL::uuid
        END AS supplier_id,
        CASE
            WHEN (allocation_type = 'account'::text) THEN 'refund_on_control_unresolved'::text
            WHEN (lines_on_this_journal > 1) THEN 'journal_shared_by_bank_lines'::text
            WHEN has_document THEN 'already_has_document'::text
            WHEN (journal_entry_id IS NULL) THEN 'no_journal'::text
            WHEN ((journal_status)::text IS DISTINCT FROM 'posted'::text) THEN 'journal_not_posted'::text
            WHEN journal_reversed THEN 'journal_reversed'::text
            WHEN (journal_imbalance <> (0)::numeric) THEN 'journal_unbalanced'::text
            WHEN (ap_movement <>
            CASE
                WHEN (direction = 'refund'::text) THEN (- amount)
                ELSE amount
            END) THEN
            CASE
                WHEN (direction = 'refund'::text) THEN 'ap_credit_mismatch'::text
                ELSE 'ap_debit_mismatch'::text
            END
            WHEN (bank_movement <>
            CASE
                WHEN (direction = 'refund'::text) THEN (- amount)
                ELSE amount
            END) THEN
            CASE
                WHEN (direction = 'refund'::text) THEN 'bank_debit_mismatch'::text
                ELSE 'bank_credit_mismatch'::text
            END
            WHEN has_document_on_other_journal THEN 'document_on_other_journal'::text
            WHEN has_cancelled_document THEN 'document_cancelled_journal_stands'::text
            WHEN (COALESCE(array_length(supplier_ids, 1), 0) = 0) THEN 'supplier_unresolved'::text
            WHEN (array_length(supplier_ids, 1) > 1) THEN 'supplier_ambiguous'::text
            WHEN (NOT supplier_has_history) THEN 'supplier_has_no_ledger_history'::text
            WHEN ((direction = 'refund'::text) AND (amount > COALESCE(on_account_credit, (0)::numeric))) THEN 'refund_exceeds_credit'::text
            WHEN (direction = 'refund'::text) THEN 'create_refund'::text
            ELSE 'create'::text
        END AS outcome,
    direction,
    on_account_credit
   FROM facts;


ALTER VIEW public.ap_payment_document_backfill_candidates OWNER TO migration_admin;

--
-- Name: VIEW ap_payment_document_backfill_candidates; Type: COMMENT; Schema: public; Owner: migration_admin
--

COMMENT ON VIEW public.ap_payment_document_backfill_candidates IS 'Every supplier-allocated bank line in either direction, plus the deposits allocated straight to the AP control account, with what the AP payment-document backfill would do with each. A refund larger than the supplier''s on-account credit as at the line''s own date is reported under refund_exceeds_credit and never minted. Reading this is the dry run; it writes nothing.';


