    decided_by text NOT NULL,
    decided_at timestamp with time zone DEFAULT now() NOT NULL,
    note text,
    roster_snapshot jsonb,
    rule_id uuid,
    CONSTRAINT bank_rule_change_decisions_decision_check CHECK ((decision = ANY (ARRAY['approved'::text, 'rejected'::text, 'superseded'::text]))),
    CONSTRAINT bank_rule_change_decisions_note_check CHECK (((note IS NULL) OR ((char_length(btrim(note)) >= 1) AND (char_length(btrim(note)) <= 500)))),
    CONSTRAINT bank_rule_change_decisions_shape_ck CHECK ((((decision = 'approved'::text) = (rule_id IS NOT NULL)) AND ((decision <> 'superseded'::text) OR ((note IS NULL) AND (roster_snapshot IS NULL)))))
);

ALTER TABLE ONLY public.bank_rule_change_decisions FORCE ROW LEVEL SECURITY;


ALTER TABLE public.bank_rule_change_decisions OWNER TO postgres;

--
-- Name: bank_rule_changes; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.bank_rule_changes (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    seq bigint NOT NULL,
    company_id uuid NOT NULL,
    rule_id uuid,
    kind text NOT NULL,
    before jsonb,
    after jsonb,
    proposed_by text NOT NULL,
    proposed_at timestamp with time zone DEFAULT now() NOT NULL,
    status text NOT NULL,
    recorded_at timestamp with time zone,
    CONSTRAINT bank_rule_changes_kind_check CHECK ((kind = ANY (ARRAY['create'::text, 'update'::text, 'toggle'::text, 'delete'::text, 'seed'::text, 'merge'::text]))),
    CONSTRAINT bank_rule_changes_rule_ck CHECK ((((status = 'applied'::text) AND (rule_id IS NOT NULL)) OR ((status = 'pending'::text) AND (kind = ANY (ARRAY['create'::text, 'update'::text, 'toggle'::text])) AND ((kind = 'create'::text) = (rule_id IS NULL))))),
    CONSTRAINT bank_rule_changes_shape_ck CHECK ((((kind = ANY (ARRAY['create'::text, 'seed'::text])) = (before IS NULL)) AND ((kind = 'delete'::text) = (after IS NULL)))),
    CONSTRAINT bank_rule_changes_status_check CHECK ((status = ANY (ARRAY['applied'::text, 'pending'::text])))
);

ALTER TABLE ONLY public.bank_rule_changes FORCE ROW LEVEL SECURITY;


ALTER TABLE public.bank_rule_changes OWNER TO postgres;

--
-- Name: bank_rule_change_states; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.bank_rule_change_states WITH (security_invoker='true') AS
 SELECT c.id,
    c.seq,
    c.company_id,
    COALESCE(c.rule_id, d.rule_id) AS rule_id,
    c.kind,
    c.before,
    c.after,
    c.proposed_by,
    c.proposed_at,
    COALESCE(d.decision, c.status) AS status,
    d.decided_by,
    d.decided_at,
    d.note AS decision_note,
    d.roster_snapshot,
    c.recorded_at
   FROM (public.bank_rule_changes c
     LEFT JOIN public.bank_rule_change_decisions d ON (((d.change_id = c.id) AND (d.company_id = c.company_id))));


ALTER VIEW public.bank_rule_change_states OWNER TO postgres;

