    CONSTRAINT customer_invoices_status_check CHECK (((status)::text = ANY (ARRAY[('draft'::character varying)::text, ('pending_approval'::character varying)::text, ('approved'::character varying)::text, ('sent'::character varying)::text, ('paid'::character varying)::text, ('partially_paid'::character varying)::text, ('overdue'::character varying)::text, ('cancelled'::character varying)::text]))),
