--
-- Name: loans; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.loans (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid NOT NULL,
    counterparty_id uuid,
    gl_account_id uuid,
    curve_id uuid,
    reference text,
    product text,
    description text,
    principal numeric(18,2) NOT NULL,
    start_date date NOT NULL,
    term_months integer NOT NULL,
    rate_mode text NOT NULL,
    margin numeric(8,4) DEFAULT 0,
    fixed_rate numeric(8,4),
    residual numeric(18,2) DEFAULT 0,
    day_count text DEFAULT 'ACTUAL_365'::text,
    reprice_mode text DEFAULT 'RESOLVE_ON_RATE_CHANGE'::text,
    skip_mode text DEFAULT 'MAINTAIN_TERM'::text,
    lump_mode text DEFAULT 'REDUCE_INSTALLMENT'::text,
    recurring_skip_months integer[] DEFAULT '{}'::integer[],
    status text DEFAULT 'active'::text,
    nca_compliant boolean DEFAULT true,
    currency text DEFAULT 'ZAR'::text,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    interest_expense_account_id uuid,
    interest_payable_account_id uuid,
    bank_account_id uuid,
    current_portion_account_id uuid,
    origination_fee numeric(18,2) DEFAULT 0,
    origination_fee_vat_type text DEFAULT 'standard'::text,
    CONSTRAINT loans_day_count_check CHECK ((day_count = ANY (ARRAY['ACTUAL_365'::text, 'ACTUAL_360'::text, '30_360'::text]))),
    CONSTRAINT loans_lump_mode_check CHECK ((lump_mode = ANY (ARRAY['REDUCE_INSTALLMENT'::text, 'MAINTAIN_INSTALLMENT'::text]))),
    CONSTRAINT loans_origination_fee_vat_type_check CHECK ((origination_fee_vat_type = ANY (ARRAY['standard'::text, 'zero'::text, 'exempt'::text]))),
    CONSTRAINT loans_rate_mode_check CHECK ((rate_mode = ANY (ARRAY['FIXED'::text, 'PRIME_PLUS'::text, 'PRIME_MINUS'::text]))),
    CONSTRAINT loans_reprice_mode_check CHECK ((reprice_mode = ANY (ARRAY['RESOLVE_ON_RATE_CHANGE'::text, 'RESOLVE_EVERY_PERIOD'::text, 'FIXED_INSTALLMENT'::text]))),
    CONSTRAINT loans_skip_mode_check CHECK ((skip_mode = ANY (ARRAY['EXTEND_TERM'::text, 'MAINTAIN_TERM'::text]))),
    CONSTRAINT loans_status_check CHECK ((status = ANY (ARRAY['active'::text, 'closed'::text, 'written_off'::text])))
);

ALTER TABLE ONLY public.loans FORCE ROW LEVEL SECURITY;


ALTER TABLE public.loans OWNER TO postgres;

--
-- Name: COLUMN loans.origination_fee; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.loans.origination_fee IS 'Upfront origination / administration fee charged at loan start (ZAR, excl VAT)';


--
-- Name: COLUMN loans.origination_fee_vat_type; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.loans.origination_fee_vat_type IS 'VAT treatment: standard (15%), zero, or exempt. Interest itself is always VAT-exempt.';


