--

CREATE TABLE public.payroll_leave_balances (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    employee_id uuid NOT NULL,
    leave_type_id uuid NOT NULL,
    balance_year integer NOT NULL,
    accrued numeric(6,2) DEFAULT 0 NOT NULL,
    taken numeric(6,2) DEFAULT 0 NOT NULL,
    pending numeric(6,2) DEFAULT 0 NOT NULL,
    balance numeric(6,2) GENERATED ALWAYS AS (((accrued - taken) - pending)) STORED,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    company_id uuid NOT NULL
);

ALTER TABLE ONLY public.payroll_leave_balances FORCE ROW LEVEL SECURITY;


ALTER TABLE public.payroll_leave_balances OWNER TO postgres;

--
-- Name: payroll_leave_requests; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.payroll_leave_requests (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    employee_id uuid NOT NULL,
    leave_type_id uuid NOT NULL,
    start_date date NOT NULL,
    end_date date NOT NULL,
    days numeric(5,2) NOT NULL,
    reason text,
    status character varying(20) DEFAULT 'pending'::character varying NOT NULL,
    approved_by uuid,
    approved_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    company_id uuid NOT NULL,
    CONSTRAINT payroll_leave_requests_status_check CHECK (((status)::text = ANY (ARRAY[('pending'::character varying)::text, ('approved'::character varying)::text, ('rejected'::character varying)::text, ('cancelled'::character varying)::text])))
);

ALTER TABLE ONLY public.payroll_leave_requests FORCE ROW LEVEL SECURITY;


ALTER TABLE public.payroll_leave_requests OWNER TO postgres;

--
-- Name: payroll_leave_types; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.payroll_leave_types (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid NOT NULL,
    name character varying(100) NOT NULL,
    bcea_type character varying(30),
    accrual_rule character varying(20) DEFAULT 'monthly'::character varying NOT NULL,
    accrual_days numeric(5,2) DEFAULT 1.25 NOT NULL,
    max_carry_over numeric(5,2),
    is_paid boolean DEFAULT true NOT NULL,
    is_active boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT payroll_leave_types_accrual_rule_check CHECK (((accrual_rule)::text = ANY (ARRAY[('monthly'::character varying)::text, ('cycle_30_per_36'::character varying)::text, ('none'::character varying)::text]))),
    CONSTRAINT payroll_leave_types_bcea_type_check CHECK (((bcea_type)::text = ANY (ARRAY[('annual'::character varying)::text, ('sick'::character varying)::text, ('family_responsibility'::character varying)::text, ('maternity'::character varying)::text, ('paternity'::character varying)::text, ('unpaid'::character varying)::text, ('study'::character varying)::text, ('other'::character varying)::text])))
);

ALTER TABLE ONLY public.payroll_leave_types FORCE ROW LEVEL SECURITY;


ALTER TABLE public.payroll_leave_types OWNER TO postgres;

--
-- Name: payroll_loan_payment_reversals; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.payroll_loan_payment_reversals (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid NOT NULL,
    loan_id uuid NOT NULL,
    run_id uuid,
    period_year integer NOT NULL,
    period_month integer NOT NULL,
    principal_reversed numeric(14,2) NOT NULL,
    interest_reversed numeric(14,2) DEFAULT 0 NOT NULL,
    reapplied boolean DEFAULT false NOT NULL,
    reversed_at timestamp with time zone DEFAULT now() NOT NULL,
    stranded boolean DEFAULT false NOT NULL,
    CONSTRAINT payroll_loan_payment_reversals_period_month_check CHECK (((period_month >= 1) AND (period_month <= 12)))
);

ALTER TABLE ONLY public.payroll_loan_payment_reversals FORCE ROW LEVEL SECURITY;


ALTER TABLE public.payroll_loan_payment_reversals OWNER TO postgres;

--
-- Name: TABLE payroll_loan_payment_reversals; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.payroll_loan_payment_reversals IS 'Tombstones for payroll_loan_payments rows deleted when a payroll run was recalculated. reapplied = false means the instalment was undone and not taken again.';


--
-- Name: COLUMN payroll_loan_payment_reversals.stranded; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.payroll_loan_payment_reversals.stranded IS 'true when the reversed payment had run_id NULL — its own run was deleted and this run reclaimed the period, rather than undoing its own earlier work.';


--
-- Name: payroll_loan_payments; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.payroll_loan_payments (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    loan_id uuid NOT NULL,
    run_id uuid,
    period_year integer NOT NULL,
    period_month integer NOT NULL,
    opening_balance numeric(14,2) NOT NULL,
    interest_charged numeric(14,2) DEFAULT 0 NOT NULL,
    principal_paid numeric(14,2) NOT NULL,
    fringe_benefit numeric(14,2) DEFAULT 0 NOT NULL,
    closing_balance numeric(14,2) NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    schedule_row_id uuid,
    loan_balance_before numeric(14,2),
    CONSTRAINT payroll_loan_payments_period_month_check CHECK (((period_month >= 1) AND (period_month <= 12)))
);


ALTER TABLE public.payroll_loan_payments OWNER TO postgres;

--
-- Name: COLUMN payroll_loan_payments.fringe_benefit; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.payroll_loan_payments.fringe_benefit IS 'SARS 3801 taxable value — (official_rate - loan_rate) * opening_balance / 12 when loan rate < official rate.';


--
-- Name: COLUMN payroll_loan_payments.schedule_row_id; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.payroll_loan_payments.schedule_row_id IS 'The payroll_loan_schedule row this payment flagged paid. NULL on rows written before migration 622.';


--
-- Name: COLUMN payroll_loan_payments.loan_balance_before; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.payroll_loan_payments.loan_balance_before IS 'payroll_loans.outstanding_balance immediately before this payment was applied, so a reversal restores it exactly. NULL on rows written before migration 622.';


--
-- Name: payroll_loan_schedule; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.payroll_loan_schedule (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    loan_id uuid NOT NULL,
    sequence integer NOT NULL,
    due_period_year integer NOT NULL,
    due_period_month integer NOT NULL,
    opening_balance numeric(14,2) NOT NULL,
    interest numeric(14,2) DEFAULT 0 NOT NULL,
    principal numeric(14,2) NOT NULL,
    installment numeric(14,2) NOT NULL,
    closing_balance numeric(14,2) NOT NULL,
    paid_flag boolean DEFAULT false NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT payroll_loan_schedule_due_period_month_check CHECK (((due_period_month >= 1) AND (due_period_month <= 12))),
    CONSTRAINT payroll_loan_schedule_sequence_check CHECK ((sequence >= 1))
);


ALTER TABLE public.payroll_loan_schedule OWNER TO postgres;

--
-- Name: payroll_loans; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.payroll_loans (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid NOT NULL,
    employee_id uuid NOT NULL,
    loan_number text NOT NULL,
    description text NOT NULL,
    principal numeric(14,2) NOT NULL,
    annual_interest_rate numeric(6,4) DEFAULT 0 NOT NULL,
    term_months integer NOT NULL,
    method text NOT NULL,
    start_date date NOT NULL,
    first_deduction_period_year integer NOT NULL,
    first_deduction_period_month integer NOT NULL,
    status text DEFAULT 'active'::text NOT NULL,
    outstanding_balance numeric(14,2) NOT NULL,
    total_interest_charged numeric(14,2) DEFAULT 0 NOT NULL,
    total_principal_paid numeric(14,2) DEFAULT 0 NOT NULL,
    notes text,
    created_by character varying(255),
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    settled_at timestamp with time zone,
    CONSTRAINT payroll_loans_annual_interest_rate_check CHECK ((annual_interest_rate >= (0)::numeric)),
    CONSTRAINT payroll_loans_first_deduction_period_month_check CHECK (((first_deduction_period_month >= 1) AND (first_deduction_period_month <= 12))),
    CONSTRAINT payroll_loans_method_check CHECK ((method = ANY (ARRAY['declining_balance'::text, 'straight_line'::text, 'interest_free'::text]))),
    CONSTRAINT payroll_loans_principal_check CHECK ((principal > (0)::numeric)),
    CONSTRAINT payroll_loans_status_check CHECK ((status = ANY (ARRAY['active'::text, 'settled'::text, 'written_off'::text, 'cancelled'::text]))),
    CONSTRAINT payroll_loans_term_months_check CHECK (((term_months >= 1) AND (term_months <= 600)))
);

ALTER TABLE ONLY public.payroll_loans FORCE ROW LEVEL SECURITY;


ALTER TABLE public.payroll_loans OWNER TO postgres;

--
-- Name: TABLE payroll_loans; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.payroll_loans IS 'Employee loan agreements. Balance is maintained as a running total in outstanding_balance. Schedule and payments tables give the full audit trail.';


--
-- Name: COLUMN payroll_loans.method; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.payroll_loans.method IS 'declining_balance = equal installments (interest re-calculated on outstanding); straight_line = equal principal each period + interest on outstanding; interest_free = principal only, fringe benefit if official rate > 0.';


--
-- Name: payroll_run_headers; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.payroll_run_headers (
