    total_uif numeric(14,2) DEFAULT 0 NOT NULL,
    total_sdl numeric(14,2) DEFAULT 0 NOT NULL,
    total_eti numeric(14,2) DEFAULT 0 NOT NULL,
    total_net numeric(14,2) DEFAULT 0 NOT NULL,
    employee_count integer DEFAULT 0 NOT NULL,
