    CONSTRAINT payroll_run_headers_status_check CHECK (((status)::text = ANY (ARRAY[('draft'::character varying)::text, ('calculated'::character varying)::text, ('approved'::character varying)::text, ('paid'::character varying)::text, ('cancelled'::character varying)::text])))
);

ALTER TABLE ONLY public.payroll_run_headers FORCE ROW LEVEL SECURITY;


ALTER TABLE public.payroll_run_headers OWNER TO postgres;

