--
-- Name: paystack_payment_requests; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.paystack_payment_requests (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid NOT NULL,
    purpose text NOT NULL,
    customer_invoice_id uuid,
    subscription_charge_id uuid,
    flow_purchase_id uuid,
    paystack_reference text NOT NULL,
    paystack_access_code text,
    paystack_transaction_id bigint,
    paystack_authorization_code text,
    paystack_customer_code text,
    authorization_url text,
    amount_cents bigint NOT NULL,
    currency character(3) DEFAULT 'ZAR'::bpchar NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    failure_reason text,
    channel text,
    payer_name text,
    payer_email text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    completed_at timestamp with time zone,
    mandate_id uuid,
    portal_payment_link_id uuid,
    CONSTRAINT paystack_payment_requests_amount_cents_check CHECK ((amount_cents > 0)),
    CONSTRAINT paystack_payment_requests_purpose_check CHECK ((purpose = ANY (ARRAY['customer_invoice'::text, 'subscription_charge'::text, 'authorization'::text, 'flow_bundle'::text]))),
    CONSTRAINT paystack_payment_requests_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'completed'::text, 'failed'::text, 'cancelled'::text, 'abandoned'::text]))),
    CONSTRAINT paystack_pr_flow_has_purchase CHECK (((purpose <> 'flow_bundle'::text) OR (flow_purchase_id IS NOT NULL))),
    CONSTRAINT paystack_pr_invoice_has_invoice CHECK (((purpose <> 'customer_invoice'::text) OR (customer_invoice_id IS NOT NULL))),
    CONSTRAINT paystack_pr_subcharge_has_charge CHECK (((purpose <> 'subscription_charge'::text) OR (subscription_charge_id IS NOT NULL)))
);

ALTER TABLE ONLY public.paystack_payment_requests FORCE ROW LEVEL SECURITY;


ALTER TABLE public.paystack_payment_requests OWNER TO postgres;

