--
-- Name: vat_gate_overrides; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.vat_gate_overrides (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid NOT NULL,
    target_type text NOT NULL,
    target_id uuid,
    period_start date NOT NULL,
    period_end date NOT NULL,
    actor text NOT NULL,
    reason text NOT NULL,
    exception_snapshot jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT vat_gate_overrides_actor_ck CHECK ((btrim(actor) <> ''::text)),
    CONSTRAINT vat_gate_overrides_range_ck CHECK ((period_end >= period_start)),
    CONSTRAINT vat_gate_overrides_reason_ck CHECK ((btrim(reason) <> ''::text)),
    CONSTRAINT vat_gate_overrides_target_type_check CHECK ((target_type = ANY (ARRAY['vat_period_lock'::text, 'sars_submission'::text])))
);

ALTER TABLE ONLY public.vat_gate_overrides FORCE ROW LEVEL SECURITY;


ALTER TABLE public.vat_gate_overrides OWNER TO postgres;

--
-- Name: vat_period_locks; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.vat_period_locks (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid NOT NULL,
    period_start date NOT NULL,
    period_end date NOT NULL,
    output_tax numeric(15,2) NOT NULL,
    input_tax numeric(15,2) NOT NULL,
    net_vat numeric(15,2) NOT NULL,
    posted_through timestamp with time zone NOT NULL,
    locked_by text NOT NULL,
    actor_type text DEFAULT 'agent'::text NOT NULL,
    actor_token_jti text,
    locked_at timestamp with time zone DEFAULT now() NOT NULL,
    notes text,
    unlocked_at timestamp with time zone,
    unlocked_by text,
    unlock_reason text,
    CONSTRAINT vat_period_locks_actor_ck CHECK ((actor_type = ANY (ARRAY['human'::text, 'agent'::text, 'system'::text]))),
    CONSTRAINT vat_period_locks_range_ck CHECK ((period_end >= period_start)),
    CONSTRAINT vat_period_locks_unlock_ck CHECK ((((unlocked_at IS NULL) AND (unlocked_by IS NULL) AND (unlock_reason IS NULL)) OR ((unlocked_at IS NOT NULL) AND (unlocked_by IS NOT NULL) AND (btrim(unlocked_by) <> ''::text) AND (unlock_reason IS NOT NULL) AND (btrim(unlock_reason) <> ''::text))))
);

ALTER TABLE ONLY public.vat_period_locks FORCE ROW LEVEL SECURITY;


ALTER TABLE public.vat_period_locks OWNER TO postgres;

