--
-- Name: TABLE waitlist_signups; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.waitlist_signups IS 'Pre-launch lead capture — public /api/waitlist endpoint inserts here. Not tied to a company_id or user; promoted to a real account after launch.';


--
-- Name: COLUMN waitlist_signups.signup_type; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.waitlist_signups.signup_type IS 'direct = own business, accountant = bureau (manages multiple client companies). Captured at signup, drives onboarding routing at launch.';


--
-- Name: COLUMN waitlist_signups.practice_name; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.waitlist_signups.practice_name IS 'Accounting practice/firm name — only populated when signup_type=accountant.';


--
-- Name: COLUMN waitlist_signups.annual_turnover_cents; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.waitlist_signups.annual_turnover_cents IS 'Self-declared annual turnover in ZAR cents; null = undeclared. Seeds companies.annual_turnover_cents on promotion to real tenant. < R1M flags PAYG eligibility.';


--
-- Name: COLUMN waitlist_signups.promoted_at; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.waitlist_signups.promoted_at IS 'Timestamp when an admin promoted this lead into a real companies row. NULL = still pending.';


--
-- Name: COLUMN waitlist_signups.promoted_company_id; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.waitlist_signups.promoted_company_id IS 'FK to the companies row created when this lead was promoted. NULL while pending.';


