--
-- Name: entity_changes entity_changes_read; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY entity_changes_read ON public.entity_changes FOR SELECT TO app_user USING (((company_id = app.current_company_id()) AND (company_id IN ( SELECT auth.user_companies() AS user_companies)) AND
CASE
    WHEN (entity_type = ANY (ARRAY['supplier'::text, 'customer'::text, 'gl_account'::text])) THEN true
    WHEN (entity_type = 'payroll_employee'::text) THEN COALESCE((public.company_member_actor_role(company_id) = ANY (ARRAY['owner'::text, 'admin'::text, 'manager'::text])), false)
    ELSE COALESCE((public.company_member_actor_role(company_id) = ANY (ARRAY['owner'::text, 'admin'::text])), false)
END));


