           FROM public.company_users
          WHERE (company_users.user_id = auth.uid()))))))) WITH CHECK ((EXISTS ( SELECT 1
   FROM public.payroll_batches b
  WHERE ((b.id = payroll_batch_lines.batch_id) AND (b.company_id = app.current_company_id()) AND (b.company_id IN ( SELECT company_users.company_id
