CREATE POLICY tenant_isolation_via_parent ON public.procurement_documents TO app_user USING (((((entity_type)::text = 'supplier_invoice'::text) AND (EXISTS ( SELECT 1
   FROM public.supplier_invoices p
  WHERE ((p.id = procurement_documents.entity_id) AND (p.company_id IN ( SELECT company_users.company_id
           FROM public.company_users
          WHERE (company_users.user_id = auth.uid()))))))) OR (((entity_type)::text = 'customer_invoice'::text) AND (EXISTS ( SELECT 1
   FROM public.customer_invoices p
  WHERE ((p.id = procurement_documents.entity_id) AND (p.company_id IN ( SELECT company_users.company_id
           FROM public.company_users
          WHERE (company_users.user_id = auth.uid()))))))) OR (((entity_type)::text = 'supplier_payment'::text) AND (EXISTS ( SELECT 1
   FROM public.supplier_payments p
  WHERE ((p.id = procurement_documents.entity_id) AND (p.company_id IN ( SELECT company_users.company_id
           FROM public.company_users
          WHERE (company_users.user_id = auth.uid()))))))) OR (((entity_type)::text = 'customer_payment'::text) AND (EXISTS ( SELECT 1
   FROM public.customer_payments p
  WHERE ((p.id = procurement_documents.entity_id) AND (p.company_id IN ( SELECT company_users.company_id
           FROM public.company_users
          WHERE (company_users.user_id = auth.uid()))))))) OR (((entity_type)::text = 'credit_note'::text) AND (EXISTS ( SELECT 1
   FROM public.credit_notes p
  WHERE ((p.id = procurement_documents.entity_id) AND (p.company_id IN ( SELECT company_users.company_id
           FROM public.company_users
          WHERE (company_users.user_id = auth.uid()))))))) OR (((entity_type)::text = 'purchase_order'::text) AND (EXISTS ( SELECT 1
   FROM public.purchase_orders p
  WHERE ((p.id = procurement_documents.entity_id) AND (p.company_id IN ( SELECT company_users.company_id
           FROM public.company_users
          WHERE (company_users.user_id = auth.uid()))))))))) WITH CHECK (((((entity_type)::text = 'supplier_invoice'::text) AND (EXISTS ( SELECT 1
   FROM public.supplier_invoices p
  WHERE ((p.id = procurement_documents.entity_id) AND (p.company_id = app.current_company_id()))))) OR (((entity_type)::text = 'customer_invoice'::text) AND (EXISTS ( SELECT 1
   FROM public.customer_invoices p
  WHERE ((p.id = procurement_documents.entity_id) AND (p.company_id = app.current_company_id()))))) OR (((entity_type)::text = 'supplier_payment'::text) AND (EXISTS ( SELECT 1
   FROM public.supplier_payments p
  WHERE ((p.id = procurement_documents.entity_id) AND (p.company_id = app.current_company_id()))))) OR (((entity_type)::text = 'customer_payment'::text) AND (EXISTS ( SELECT 1
   FROM public.customer_payments p
  WHERE ((p.id = procurement_documents.entity_id) AND (p.company_id = app.current_company_id()))))) OR (((entity_type)::text = 'credit_note'::text) AND (EXISTS ( SELECT 1
   FROM public.credit_notes p
  WHERE ((p.id = procurement_documents.entity_id) AND (p.company_id = app.current_company_id()))))) OR (((entity_type)::text = 'purchase_order'::text) AND (EXISTS ( SELECT 1
